(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["cs"] = {"ui":{"skip":"Přeskočit na obsah","back":"← Zpět na AI-gile","lang.button":"Jazyk: {name}","lang.dialog":"Vyber jazyk","lang.search":"Hledat jazyk","lang.none":"Žádný jazyk neodpovídá","lang.notYet":"{name} zatím není přeloženo","theme.aria":"Přepnout motiv: světlý, tmavý nebo černý","theme.toLight":"Přepnout na světlý motiv","theme.toDark":"Přepnout na tmavý motiv","theme.toBlack":"Přepnout na černý motiv (skutečná černá, šetrná k OLED displejům)","words.underline":"Podtrhnout tato slova na stránce","words.underlineHelp":"Najeď myší na tečkovaně podtržené slovo nebo na něj klepni a uvidíš, co znamená.","words.col.todo":"Karty vybrané na teď: tým začne právě těmito.","words.col.doing":"Na této kartě právě pracuje AI.","words.col.review":"Jedna AI práci dokončila; další ji zkontroluje, než se dostane k tobě.","words.col.verify":"Čeká na tebe: vyzkoušej to a řekni, jestli to funguje.","words.col.team":"Tvoje poznámky nebo odpovědi, které čekají, až si je tým převezme.","words.col.done":"Hotovo a schváleno.","index.title":"AI-gile: tvůj AI vývojářský tým na jedné tabuli","index.description":"AI-gile je kanbanová tabule pro týmy AI programátorů. Pracují, zatímco spíš; ty dostaneš jednu krátkou hromádku věcí k rozhodnutí, vyzkoušení a schválení.","hero.logoAlt":"Ikona tabule AI-gile","hero.h1.html":"Tvůj AI vývojářský tým na jedné&nbsp;tabuli.","hero.alpha":"🐣 Uzavřená pre-alfa","hero.alphaTitle":"Brzy a nehotové: díky, že to zkoušíš!","hero.lede":"Staví, zatímco spíš. Ráno tě čeká jedna krátká hromádka: pár otázek, pár věcí k vyzkoušení, jeden dva fialové diamanty. Klik, schváleno, zpátky ke kávě.","dl.windows":"Aplikace pro Windows","dl.browser":"Spustit v prohlížeči","dl.messenger":"📱 Messenger do mobilu","dl.soon":"Brzy","dl.notify":"🔔 Dej mi vědět, až se otevře","dl.notifySmall":"Alfa nebo beta","hero.secondary":"Agile, jen tým nepotřebuje stand-up u kávy. (Stand-upy ale dělá stejně.)","pitch.h2":"AI-gile na tolik slov, kolik chceš","pitch.lede":"Vyber délku, od jednoho slova po 144. Každá délka je vlastní popis napsaný přesně pro ni. Posuň jezdec nebo použij šipky.","pitch.rangeLabel":"Délka ve slovech","pitch.dice":"🎲 další verze","pitch.words.one":"{n} slovo","pitch.words.other":"{n} slov","pitch.letters.one":"{n} písmeno","pitch.letters.other":"{n} písmen","pitch.chars.one":"{n} znak","pitch.chars.other":"{n} znaků","count.line.html.one":"{n} karta právě teď na tabuli","count.line.html.other":"{n} karet právě teď na tabuli","people.humans.html.one":"👥 {n} člověk","people.humans.html.other":"👥 {n} lidí","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agentů","people.working.html.one":"⚡ {n} právě pracuje","people.working.html.other":"⚡ {n} právě pracuje","pre.title":"AI-gile: něco se tu staví","pre.description":"Něco se tu staví. Tabule, na které AI týmy staví, o co si řekneš, a cestou tě učí. Zatím uzavřená pre-alfa s přáteli.","pre.h1":"Něco se tu staví. 🤫","pre.line":"Tabule, na které AI týmy staví, o co si řekneš, a cestou tě učí. Zatím uzavřená pre-alfa s přáteli.","pre.btn":"🔔 Dej mi vědět, až se otevře","pre.peek":"Za sklem: skutečná tabule, živě. Každá karta je barevný proužek.","pre.peekFake":"Za sklem: takhle vypadá tabule v plném proudu.","pre.night":"🌙 Noční hlídač velí · 😴 člověk odpočívá","features.aria":"Co umí","f.pile.h":"Jedna hromádka pro tebe","f.pile.html":"<b>Pro tebe</b> shromažďuje všechno, co čeká na tebe, napříč všemi projekty: otázky, věci k vyzkoušení, úkoly jen pro člověka. Tvoje fronta říká, co je na řadě a jak dlouho to potrvá.","f.sleep.h":"Týmy, které pracují, zatímco spíš","f.sleep.p":"Každý projekt má vedoucího a tým AI agentů. Okomentuj kartu a tým se probudí, odvede práci a vrátí ti ji s kroky, které zvládne i unavený člověk.","f.tester.h":"Nejdřív to zkontroluje AI tester","f.tester.p":"Než se k tobě cokoli dostane, tester projde kroky v kopii aplikace a ukáže, co viděl, se snímkem obrazovky. Prolistuj ty úspěšné a schval je jedním klikem.","f.proof.h":"Důkazy, ne sliby","f.proof.p":"Každé předání ukazuje, co se změnilo: soubory, rozdíly, snímky obrazovky. Žádné otevírání každé aplikace, abys zjistil, jestli je hotovo.","f.chat.h":"Chat s tvými vedoucími","f.chat.p":"Lišta jako na Discordu: jedna ikona na projekt, fialové diamanty u toho, co potřebuje tebe. Napiš vedoucímu nápad; promění ho v karty a plán s tlačítkem ✅ Go.","f.tidy.h":"Udržuje si pořádek","f.tidy.p":"Související karty se slijí v jednu, zmatené názvy se opraví a kontrola tokenů drží kód štíhlý. Méně věcí k přepínání, méně k přemýšlení.","f.private.h":"Tvoje, na tvém počítači","f.private.li1":"Tabule běží na tvém vlastním stroji a odpovídá jen tobě.","f.private.li2":"Soukromé zprávy mezi lidmi jsou šifrované end-to-end.","f.private.li3":"Žádné účty, žádné sledování, žádné cookies.","f.lang.h":"Ve tvém jazyce","f.lang.p":"Přes 120 jazyků, od nizozemštiny, velštiny a japonštiny po pirátštinu, Yodu a klingonštinu, s rychlým přepnutím zpět do angličtiny kvůli odborným výrazům.","f.service.h":"Od nápadu ke skutečné službě","f.service.p":"Postavil jsi s AI něco, co teď lidé používají? Označ to jako službu a nástěnka ti pomůže ji dobře provozovat: kontroly dostupnosti, veřejná stavová stránka, incidenty se sepsaným rozborem, změny, které potřebují Go, zálohy kontrolované každý den. Nápověda tě naučí každý krok průběžně.","msgr.h2":"AI-gile Messenger: tvůj tým v kapse","msgr.p1":"Mluv se svým AI týmem bez otevírání boardu. Piš si s vedoucími svých projektů i s přáteli, prohlédni si testovací kroky karty a odpověz na ně, všechno z mobilu.","msgr.p2":"Pro spárování naskenuj QR kód na svém boardu. Poprvé? Přátelský demo chat tě vším provede.","msgr.when":"Nejdřív Android, potom webová verze pro mobily a iPhone.","msgr.who":"Vedoucí tvého projektu","msgr.b1":"Oprava tmavého režimu je hotová. Chceš testovací kroky?","msgr.b2":"Jo, prosím!","msgr.b3":"1. Otevři Nastavení. 2. Vyber Tmavý. Vypadá to dobře?","tl.aria":"Časová osa od prvního rozhovoru po plán dalšího vývoje","tl.h2":"Od prvního chatu k tomu, co bude dál","tl.lede":"Skutečná data a časy ve tvém časovém pásmu. Po dnešku je to plán, bez slíbených termínů.","tl.today":"Dnes","tl.planned":"plánováno","tl.doing":"rozpracováno","tl.cards.one":"{n} karta","tl.cards.other":"{n} karet","join.h2":"Přidej se","join.lede":"AI-gile staví vousatý podivín s AuDHD a pár boji s duševním zdravím, a k tomu velké množství trpělivých agentů. Zatím je soukromé, v uzavřené alfě mezi přáteli. Chceš si to vyzkoušet, až se otevře?","join.btn":"Zaregistrovat zájem","join.small":"Napíšeme ti e-mail, nic jiného","footer.tag":"AI-gile. Žádné sledování, žádné cookies, žádná stand-up káva.","footer.licence":"Firemní licence","footer.status":"Stav","footer.privacy":"Co uchováváme","footer.thanks":"Hovory díky ChilledChat","form.sending":"Odesílám…","form.failed":"Nepovedlo se: zkus to později.","form.offline":"AI-gile se nepodařilo zastihnout: zkus to později.","form.keep":"Použijeme to jen k tomu, abychom ti odpověděli, a pak to smažeme. Žádné sledování, žádné cookies.","form.keepLink":"Co uchováváme","interest.title":"AI-gile: dej mi vědět, až se otevře alfa","interest.description":"Nech nám e-mail a dozvíš se, kdy se otevře uzavřená alfa nebo beta AI-gile.","interest.h1":"🔔 Dej mi vědět, až se otevře","interest.lede":"AI-gile je v uzavřené pre-alfě. Nech nám e-mail a napíšeme ti jednou, až pro tebe bude místo.","interest.email":"Tvůj e-mail","interest.which":"Které testování?","interest.alpha":"Uzavřená alfa: brzy, hrubé, hodně změn","interest.beta":"Beta: stabilnější, později","interest.both":"Obojí, co přijde dřív","interest.submit":"Zapsat mě na seznam","interest.thanks":"Díky! Jsi na seznamu.","licence.title":"AI-gile: firemní licence","licence.description":"Používáš AI-gile ve firmě? Požádej o bezplatnou firemní licenci.","licence.h1":"📜 Firemní licence","licence.lede":"Používáš AI-gile v práci? Napiš nám, kdo jsi a co děláš. Pokud to dělá něco dobrého, licence je zdarma.","licence.company":"Firma","licence.website":"Web","licence.what":"Čím se zabýváš","licence.how":"Jak to pomáhá světu","licence.email":"E-mail","licence.submit":"Odeslat žádost","licence.thanks":"Díky! Odpovíme e-mailem.","status.title":"Stav AI-gile","status.h1":"Stav AI-gile","status.quiet":"Klid","status.intro":"Funguje AI-gile právě teď? Tato stránka každých 5 minut kontroluje web, sdílení tabulí, hovory a stahování.","status.up":"Funguje (odpověď za {ms} ms)","status.slow":"Na poslední kontrolu neodpověděl, zkoušíme znovu","status.down":"Nefunguje: neodpověděl na poslední dvě kontroly","status.svc.web":"Web","status.svc.web.offers":"Tento web: co je AI-gile a formulář zájmu","status.svc.boards":"Sdílení tabulí","status.svc.boards.offers":"Veřejné tabule, zprávy mezi přáteli a pozvánky","status.svc.calls":"Hovory","status.svc.calls.offers":"Hlas, video a sdílení obrazovky v AI-gile","status.svc.download":"Stahování","status.svc.download.offers":"Instalátor pro Windows a odkazy s pozvánkou","status.checking":"Kontroluji…","status.offline":"Službu stavu se právě nedaří zastihnout (zkouším znovu)","status.updated":"aktualizováno {ago}","status.justNow":"právě teď","status.min":"před {n} min","status.hours":"před {n} h","status.days":"před {n} d","privacy.title":"AI-gile: co uchováváme","privacy.h1":"Co uchováváme","privacy.lede":"Ve zkratce: jen to, co nám pošleš, a ne nadlouho.","privacy.only":"Jen to, co nám pošleš: co napíšeš do formuláře, třeba svůj e-mail. Nic jiného o tobě.","privacy.sealed":"Je to zapečetěné, takže to náš server nepřečte: v tvém prohlížeči, ještě než to odejde (ve starším prohlížeči hned, jak to dorazí). Otevřít to umí jen naše vlastní tabule.","privacy.server":"Ze serveru se to smaže, jakmile to dorazí na naši tabuli. Cokoli, co tam zůstane i po 30 dnech, se smaže tak jako tak.","privacy.board":"Na naší tabuli to necháme jen do chvíle, než ti odpovíme, pak to smažeme i tam.","privacy.none":"Žádné sledování, žádné cookies, žádná analytika.","privacy.local":"Tvůj jazyk a volba světlého nebo tmavého motivu zůstávají ve tvém vlastním prohlížeči. Nikdy se nám neposílají.","privacy.ask":"Chceš to smazat dřív? Odpověz na náš e-mail a řekni nám to.","live.h2":"Sledujte, jak se to staví, živě","live.caption":"Každá karta je skrytá: vidíte tvar práce, ne slova.","live.watching.one":"živě: {n} sleduje","live.watching.other":"živě: {n} sledují","live.last.now":"Poslední karta přesunuta právě teď","live.last.min.one":"Poslední karta přesunuta před {n} min","live.last.min.other":"Poslední karta přesunuta před {n} min","live.last.hour.one":"Poslední karta přesunuta před {n} hodinou","live.last.hour.other":"Poslední karta přesunuta před {n} hodinami","live.last.day.one":"Poslední karta přesunuta před {n} dnem","live.last.day.other":"Poslední karta přesunuta před {n} dny","live.offline":"Živá tabule si dává pauzu. Zkuste to brzy znovu.","live.cols":"Backlog|K udělání|Rozpracováno|Tým kontroluje|Čeká na tvůj test|Pro tým|Hotovo","pitch.words.few":"{n} slova","pitch.words.many":"{n} slova","pitch.letters.few":"{n} písmena","pitch.letters.many":"{n} písmena","pitch.chars.few":"{n} znaky","pitch.chars.many":"{n} znaku","count.line.html.few":"{n} karty právě teď na tabuli","count.line.html.many":"{n} karty právě teď na tabuli","tl.cards.few":"{n} karty","tl.cards.many":"{n} karty"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Delegováno."]},{"n":2,"texts":["Robotický kanban.","Agenti, uspořádaně.","Nápady, postavené."]},{"n":3,"texts":["Kanban pro roboty.","Z nápadů funkce.","Agentní kanban zdarma."]},{"n":5,"texts":["Kanbanová tabule řízená AI agenty.","Ty píšeš karty. Agenti staví.","Zdarma, lokální, otestované, trochu praštěné."]},{"n":8,"texts":["Kanbanová tabule zdarma, na které pracují AI agenti.","Napiš nápad. Agenti ho postaví. Ty ho schválíš.","Agile pro jednoho člověka a spoustu trpělivých robotů."]},{"n":13,"texts":["Kanbanová tabule na tvém počítači, kde karty zpracovávají AI agenti.","Napiš nápad. Tým agentů ho postaví. Pak ho zkontroluje tester a ty řekneš ano.","Zdarma, bez účtů, bez sledování: tabule, pár robotů a ty ve vedení."]},{"n":21,"texts":["AI-gile je kanbanová tabule pro práci s AI agenty, kteří programují. Oni berou karty, ty je zkoušíš a schvaluješ.","Každý projekt dostane vedoucího a tým AI agentů. Okomentuj kteroukoli kartu a tým se hned pustí do práce.","Osobní tabule úkolů zdarma, která běží na tvém vlastním počítači. Pracují na ní roboti. Ano říká ten pravý: ty."]},{"n":34,"texts":["Nápady dáváš na tabuli. Tým AI agentů z nich vyrobí fungující funkce, otestuje je a vrátí ti je s kroky k vyzkoušení. Nic se nepočítá jako hotové, dokud to neřekneš ty.","AI-gile je domácí kanbanová tabule, kterou Rich postavil s velkou pomocí agentů, jež dnes sama řídí. Je zdarma, běží na tvém počítači a sdílí se s přáteli, neprodává se.","Představ si obyčejnou kanbanovou tabuli se sloupci od Backlogu po Hotovo, jenže karty si berou AI agenti. Hlásí postup, ptají se, když uvíznou, a vždycky čekají na tvůj palec nahoru."]},{"n":55,"texts":["AI-gile je kanbanová tabule, kde tým tvoří AI agenti. Každý projekt má vedoucího, který plánuje práci, a pomocníky, kteří ji staví. Když je funkce hotová, AI tester ji vyzkouší a udělá snímek obrazovky, pak přistane na tvé hromádce. Schval ji, nebo napiš komentář a oni ji přepracují.","Začalo to jako způsob, jak si jeden člověk hlídal spoustu AI programátorských relací najednou, a vyrostla z toho pořádná tabule. Běží na tvém stroji, nepotřebuje účet a nemá žádné sledování. Pro přátele a zvědavce je zdarma. Také je nedodělané, takže čekej hrubé hrany a občasné překvapení.","Tady je poctivá verze. Nápady pořád musíš mít ty a výsledky pořád musíš kontrolovat ty. AI-gile dělá všechno mezi tím: drží karty v pořádku, probudí správného agenta, když přidáš komentář, ukáže přesně, co se změnilo, a všechno to složí do jedné krátké hromádky pro tebe."]},{"n":89,"texts":["AI-gile je kanbanová tabule zdarma, kterou provozuješ na vlastním počítači. Místo lidí má každý projekt tým AI agentů: vedoucího, který tvé nápady mění v karty a plán, a pomocníky, kteří si karty berou podle priority. Když je něco postavené, AI tester projde testovací kroky a ukáže ti, co viděl. Potom to čeká na jedné hromádce nazvané Pro tebe. Buď to schválíš, nebo napíšeš komentář a tým to zkusí znovu. Do sloupce Hotovo se nic nedostane bez tebe.","Pár věcí, které bys nečekal. Noční hlídka doplňuje sloupec K udělání, zatímco spíš, a vybírá karty, které od tebe nepotřebují žádnou odpověď. Počítadlo tokenů ukazuje, kolik agenti spotřebovali dnes a tento týden, a Režim bez tokenů jim řekne, ať přestanou utrácet. Můžeš psát přátelům a soukromé zprávy jsou šifrované end-to-end. Tabule mluví zhruba 120 jazyky, včetně nizozemštiny, vlámštiny, pirátštiny a klingonštiny. Nic z toho nestojí ani korunu a nikdo se ti to ani nesnaží prodat.","AI-gile je malý osobní projekt, žádná firma. Rich chtěl opečovávat několik AI programátorských projektů, aniž by musel otevírat každou aplikaci a kontrolovat je, tak mu s agenty postavili tabuli, a pak na ní postavili zbytek sebe sama. Je v uzavřené pre-alfě, což znamená, že funguje, většinou, pro hrstku přátel. Není tu žádný ceník, žádný newsletter a žádný plán růstu. Zní to užitečně? Až se to trochu víc otevře, můžeš požádat o vyzkoušení."]},{"n":144,"texts":["AI-gile je kanbanová tabule pro jednoho člověka a spoustu AI agentů. Běží na tvém vlastním počítači a je úplně zdarma. Přidáváš projekty a každý projekt dostane vedoucího a malý tým. S vedoucím si píšeš, trochu jako na Discordu, popíšeš nápad; vedoucí z něj udělá karty a plán a pak čeká, až stiskneš Go. Tým zpracovává karty podle priority pomocí jednoduchého příkazového řádku vytvořeného pro jazykové modely. Než se cokoli vrátí k tobě, AI tester projde kroky v kopii aplikace a přiloží snímek obrazovky. Hotová práce přistane na tvé hromádce se změněnými soubory a rozdílem. Buď ji schválíš, nebo necháš komentář, tým se probudí a zkusí to znovu. Kartu do Hotovo může přesunout jen ty. Žádné účty, žádné sledování, žádné cookies: všechno zůstává u tebe doma, na tvém počítači, a nic se neplatí.","Den s AI-gile, zhruba. Večer necháš pár komentářů: tohle tlačítko je na špatném místě, tenhle seznam by měl být seřazený, mohli bychom mít tmavý režim. Jdeš spát. Agenti si komentáře přečtou, provedou změny, otestují je a vrátí ti je. Když v K udělání dojdou karty, noční hlídka ho doplní z backlogu kartami, které od tebe nepotřebují odpověď. Ráno čeká jedna krátká hromádka: pár otázek a pár věcí k vyzkoušení, každá s kroky, které zvládne i rozespalý člověk, a se snímkem, jak to funguje. Proklikáš se, dobré schválíš a zbytek pošleš zpátky. Počítadlo tokenů ukáže, co to všechno stálo, a Režim bez tokenů je tu pro skromnější týdny. Pak si dáš snídani, u které agenti zatím pomoct neumějí.","Nejdřív, čím AI-gile není. Není to startup, není na prodej a nikdo neshromažďuje tvoje data. Je to bezplatná tabule, která běží na tvém počítači, bez účtů, bez sledování a bez cookies. A čím je: jedním úhledným místem, kde vidíš všechny AI programátorské projekty najednou, s týmem agentů, který dělá karty, a s tebou, který rozhoduješ. Slučuje související karty, opravuje zmatené názvy a hlídá, aby kód zůstal štíhlý. Mluví zhruba 120 jazyky, od nizozemštiny a vlámštiny po pirátštinu a klingonštinu. Přátelé si mohou psát, soukromě a šifrovaně. Postavil ji Rich s velkým počtem trpělivých agentů, většinou za pomoci sebe sama. Je v uzavřené pre-alfě, takže místy drhne. Pokud ti to zní jako zábava, požádej hezky a třeba se dostaneš dovnitř dřív."]}],"quips":{"1":"Jedno slovo. Odvážné. Možná příliš odvážné.","3":"Tři slova. Už teď poctivější než většina stránek o produktech.","8":"Osm slov. Pořád kratší než stand-up.","21":"Délky jsou mimochodem story pointy. Samozřejmě, že jsou.","55":"Padesát pět slov. Zatímco jsi to četl, dokončily se dvě karty.","144":"To je ta dlouhá. Žádná 233 neexistuje. Agenti šli spát."}},"timeline":{"first-idea.name":"První nápad","first-idea.line":"Úplně první rozhovor, ještě než existoval jakýkoli kód.","first-board.name":"První tabule","first-board.line":"Tabule, která sleduje vlastní stavbu: karty, sloupce, přetahování, projekty.","team-roles.name":"Tým a role","team-roles.line":"Profily agentů, šablony týmů, prostory a kdo co dělá.","install.name":"Instalace a vydání","install.line":"Zip, který si přítel nainstaluje, samoaktualizace, kanály a návrat zpět.","usage-saver.name":"Šetření spotřeby","usage-saver.line":"Měř, kolik běhy stojí, drž kód štíhlý, šetři svůj limit.","friends.name":"Přátelé a sdílení","friends.line":"Soukromé zprávy, šifrované předávání, pozvánky, role a sdílené projekty.","languages.name":"Jazyky","languages.line":"Každý text obrazovky v jazykovém souboru, nejdřív nizozemština a vlámština.","ai-tester.name":"AI tester","ai-tester.line":"Tester nejdřív zkontroluje každé předání a ukáže, co viděl.","website.name":"Web","website.line":"aigile.lol, upoutávka a tato časová osa.","streaming.name":"Chat a streamování","streaming.line":"Discord, Twitch, OBS, streamerský režim, GIFy a emoji.","no-ai.name":"Edice bez AI","no-ai.line":"Tabule pro lidi, kteří programují bez AI, a veřejné tabule.","night-watch.name":"Noční hlídka","night-watch.line":"Hlídač a Scrum Master drží týmy při práci, zatímco spíš.","p-more.name":"Všechno ostatní","p-more.line":"Menší nápady, které čekají na svou řadu.","p-android.name":"Telefon a Android","p-android.line":"Dostaň se k tabuli z telefonu, pak nativní aplikace pro Android.","p-release.name":"Alfa a dál","p-release.line":"Uzavřená alfa, živý web, pak beta.","p-languages.name":"Další jazyky","p-languages.line":"130 jazyků a režim ponoření pro ty, kdo se učí.","p-engines.name":"Další AI motory","p-engines.line":"Pro každého agenta vyber Claude, Codex, Gemini, Copilot nebo Cursor.","p-pro.name":"Profesionální praxe","p-pro.line":"Štítky rizika, brány pro sloučení, karty incidentů a ochranné zábrany.","p-self.name":"Péče o tebe","p-self.line":"Režim únavy, připomínky péče o sebe a 4:20.","p-servers.name":"Servery a růst","p-servers.line":"Globální nastavení serveru, role a plánování růstu.","p-livestream.name":"Streamovací extra","p-livestream.line":"Twitch chat, vlastní emoji a veřejný živý náhled."},"words":{"button":"📖 Odborné výrazy","h":"📖 Vysvětlená slova","intro":"Bezplatné školení srozumitelně: každé slovo, na které narazíš, od prvního nápadu až po službu, na kterou se lidé spoléhají, a po cestě Agile, tvorba, udržení v bezpečí a práce s AI.","search":"Hledat slovo…","none":"Žádné slovo tomu neodpovídá.","close":"Zavřít","count":{"one":"{count} slovo","other":"{count} slov"},"groups":[{"id":"idea","name":"💡 Nápad a průzkum"},{"id":"plan","name":"🗺️ Plánování práce"},{"id":"agile","name":"🔁 Agilní způsoby práce"},{"id":"build","name":"🛠️ Stavění"},{"id":"test","name":"🧪 Testování a kvalita"},{"id":"change","name":"🔀 Bezpečné změny"},{"id":"run","name":"🛎️ Provoz služby"},{"id":"sec","name":"🔒 Bezpečnost a soukromí"},{"id":"ai","name":"🤖 Práce s AI"},{"id":"money","name":"💰 Peníze a licence"}],"list":[{"id":"discovery","g":"idea","word":"Discovery (průzkum)","text":"Rané období, kdy se zjišťuje, jaký problém stojí za řešení a pro koho, dřív než se cokoli postaví.","also":["fáze discovery","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Popis problému","text":"Jedna dvě věty o tom, kdo má problém, v čem spočívá a proč na něm záleží, aby všichni mířili na totéž.","also":["popisy problému","problem statement","popisu problému"]},{"id":"user","g":"idea","word":"Uživatel","text":"Člověk, který používá to, co stavíš. Jeho potřeby jsou důvodem, proč se vůbec pracuje.","also":["uživatelé","user","uživatele","uživatelů","uživateli","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder (zainteresovaná strana)","text":"Kdokoli, komu záleží na tom, jak práce dopadne, nebo koho se týká, třeba ti, kdo ji platí, používají ji nebo ji podporují.","also":["stakeholdeři","zainteresovaná strana","stakeholder","stakeholdera","stakeholderů","stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"Vymyšlený, ale realistický člověk, který zastupuje jeden druh uživatelů, aby se tým mohl zeptat: „Bylo by to pro Terezu snadné?“","also":["persony","personu","person","personas"]},{"id":"userresearch","g":"idea","word":"Výzkum uživatelů","text":"Mluvit se skutečnými lidmi a pozorovat je, abychom zjistili, co potřebují, místo hádání.","also":["rozhovory s uživateli","user research","user interviews"]},{"id":"journey","g":"idea","word":"Cesta uživatele","text":"Kroky, které člověk udělá, aby něco vyřídil, od prvního doslechnutí až po konec, i mimo tvůj produkt. Když je nakreslíš, uvidíš, kde se zasekávají.","also":["cesty uživatele","customer journey","user journey","cesta zákazníka","cestu uživatele","cesty zákazníka"]},{"id":"painpoint","g":"idea","word":"Bolavé místo (pain point)","text":"Něco, co lidi dnes štve nebo zdržuje. Dobré produkty taková bolavá místa odstraňují.","also":["bolavá místa","pain point","pain points","bolavého místa","bolavých míst"]},{"id":"assumption","g":"idea","word":"Předpoklad","text":"Něco, čemu věříš, ale zatím to není ověřené. Když předpoklady sepíšeš, uvidíš, co otestovat jako první.","also":["předpoklady","assumption","předpokladu","předpokladů","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypotéza","text":"Nejlepší odhad, který chceš ověřit, spolu s tím, co čekáš, že se stane, třeba „lidé se zaregistrují, když bude první měsíc zdarma“.","also":["hypotézy","hypothesis","hypotézu","hypotéz","hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"Malý plánovaný test, který ukáže, jestli nápad funguje, dřív než na něj vsadíš hodně.","also":["experimenty","experimentu","experimentů","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"Rychlý hrubý pokus, jestli nápad vůbec může fungovat. Obvykle se zahodí, jakmile znáš odpověď.","also":["PoC","proof of concept","důkaz konceptu"]},{"id":"prototype","g":"idea","word":"Prototyp","text":"Raný model produktu, často proklikávací obrázky, na kterém nápad vyzkoušíš na lidech, než ho postavíš pořádně.","also":["prototypy","prototype","prototypu","prototypů","prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe (drátěný model)","text":"Jednoduchá skica obrazovky, která ukazuje, co kde je, bez barev a skutečného obsahu.","also":["wireframe","wireframy","drátěný model","wireframu","wireframů","wireframes"]},{"id":"mockup","g":"idea","word":"Mockup (návrh vzhledu)","text":"Podrobný obrázek toho, jak bude obrazovka vypadat, se skutečnými barvami a textem, ale zatím nic nefunguje.","also":["mockup","mockupy","mock-up","návrh vzhledu","mockupu","mockupů","mockups"]},{"id":"bizcase","g":"idea","word":"Business case (zdůvodnění projektu)","text":"Důvody, proč projekt dělat: kolik stojí, co vynese nebo ušetří a jaká jsou rizika.","also":["business case","podnikatelský záměr","zdůvodnění projektu","business casy","business cases"]},{"id":"feasibility","g":"idea","word":"Proveditelnost","text":"Zda se to opravdu dá postavit a udržovat s časem, penězi a dovednostmi, které máš.","also":["proveditelné","feasibility"]},{"id":"outcome","g":"idea","word":"Dopad (outcome)","text":"Změna, kterou chceš pro lidi, třeba méně zmeškaných schůzek. Je důležitější než to, kolik toho postavíš.","also":["dopady","výsledek","outcome","dopadu","dopadů","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Výstup (output)","text":"Něco, co tým vyrobí, třeba novou obrazovku nebo report. To, že to vzniklo, ještě neznamená, že to někomu pomáhá.","also":["výstupy","output","výstupu","výstupů","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Metrika úspěchu","text":"Číslo, které říká, jestli práce splnila svůj účel, třeba víc lidí, kteří dokončí objednávku.","also":["metriky úspěchu","success metric","metriku úspěchu","metrik úspěchu","success metrics"]},{"id":"kpi","g":"idea","word":"Klíčový ukazatel výkonnosti (KPI)","text":"Důležité číslo, které sleduješ a podle kterého poznáš, jestli se daří, třeba počet registrací za týden.","also":["KPI","ukazatel KPI","key performance indicator","KPIs","ukazatele výkonnosti"]},{"id":"okr","g":"idea","word":"Cíle a klíčové výsledky (OKR)","text":"Způsob stanovování cílů: cíl říká, co chceš, a pár klíčových výsledků jsou čísla, která ukážou, že se to povedlo.","also":["OKR","OKRy","objectives and key results"]},{"id":"product","g":"plan","word":"Produkt","text":"To, co se staví a udržuje pro uživatele, třeba aplikace, web nebo nástroj.","also":["produkty","product","produktu","produktů","produktem","products"],"noTip":1},{"id":"vision","g":"plan","word":"Vize produktu","text":"Krátké prohlášení o tom, komu produkt pomáhá a kam dlouhodobě míří.","also":["product vision","vision statement","vize produktu"]},{"id":"po","g":"plan","word":"Product Owner (PO)","text":"Člověk, který rozhoduje, co se staví a v jakém pořadí, aby tým vždy pracoval na tom nejdůležitějším. V AI-gile jsi to ty.","also":["PO","product owner","vlastník produktu","product ownera","vlastníka produktu","product owners"]},{"id":"pm","g":"plan","word":"Product Manager (PM)","text":"Člověk, který hlídá směr produktu: jaké problémy řeší, pro koho a proč. PM může znamenat i projektový manažer, takže si ověř, o co jde.","also":["PM","product manager","produktový manažer","product managera","produktového manažera","product managers"]},{"id":"projmgr","g":"plan","word":"Projektový manažer","text":"Člověk, který drží projekt v čase a rozpočtu a sleduje, kdo co dělá a do kdy.","also":["projektoví manažeři","project manager","project managers","projektového manažera","projektová manažerka"]},{"id":"roadmap","g":"plan","word":"Roadmapa","text":"Hrubý plán toho, co přijde v následujících měsících, popořadě. Ukazuje směr, ne přesná data, a mění se, jak se dozvídáš víc.","also":["cestovní mapa","roadmap","roadmapy","roadmapu","roadmapě"]},{"id":"milestone","g":"plan","word":"Milník","text":"Bod v projektu, který stojí za to označit, třeba „první verze naživo“ nebo „100 uživatelů“.","also":["milníky","milestone","milníku","milníků","milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"Nejmenší verze produktu, která je pořád užitečná skutečným lidem, takže se od nich můžeš učit hned zkraje.","also":["MVP","minimální životaschopný produkt","minimum viable product","MVPs"]},{"id":"requirement","g":"plan","word":"Požadavek","text":"Něco, co hotový produkt musí umět nebo čím musí být.","also":["požadavky","requirement","požadavku","požadavků","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Rozsah","text":"Co je v práci zahrnuto a, stejně důležité, co ne.","also":["scope"]},{"id":"scopecreep","g":"plan","word":"Plížící se rozsah (scope creep)","text":"Když se do práce postupně přidává stále víc, aniž by se někdo dohodl na času či nákladech navíc, takže nikdy není úplně hotová.","also":["scope creep","feature creep","nabalování rozsahu","nabalování"]},{"id":"feature","g":"plan","word":"Funkce","text":"Jedna věc, kterou produkt pro lidi umí, třeba „obnovit heslo“.","also":["funkce","feature","funkci","funkcí","features"],"noTip":1},{"id":"epic","g":"plan","word":"Epik (epic)","text":"Velký kus práce, příliš velký na jednou, a proto se rozdělí na menší karty.","also":["epiky","epic","epics","epiku","epiků","epikem"]},{"id":"story","g":"plan","word":"Uživatelský příběh (user story)","text":"Malý kus práce napsaný z pohledu uživatele: „Jako nakupující chci uložit košík, abych se k nákupu mohl(a) vrátit později.“ Otevírá rozhovor o tom, co postavit.","also":["uživatelské příběhy","user story","user stories","uživatelského příběhu","uživatelských příběhů","story"]},{"id":"ac","g":"plan","word":"Akceptační kritéria (AC)","text":"Kontroly, kterými musí karta projít, aby se počítala za hotovou, dohodnuté před začátkem práce, třeba „košík tam pořád je po odhlášení a opětovném přihlášení“.","also":["AC","acceptance criteria","akceptační kritérium","akceptačních kritérií"]},{"id":"task","g":"plan","word":"Úkol","text":"Jedna věc k udělání, často jeden malý krok většího příběhu.","also":["úkoly","task","tasks","úkolu","úkolů","úkolem"],"noTip":1},{"id":"ticket","g":"plan","word":"Tiket (ticket)","text":"Jiné slovo pro kartu: jeden kus práce nebo jeden požadavek, sledovaný od začátku do konce.","also":["tikety","ticket","tickets","tiketu","tiketů","tiketem"]},{"id":"priority","g":"plan","word":"Priorita","text":"Jak je něco důležité nebo naléhavé ve srovnání se vším ostatním, aby nejdůležitější práce šla první.","also":["priorita","priority","prioritu","priorit","prioritou","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritizace","text":"Řazení práce podle důležitosti. Častý způsob je MoSCoW: Must have (musí být), Should have (mělo by být), Could have (mohlo by být), Won’t have (tentokrát ne).","also":["určování priorit","prioritizovat","MoSCoW","prioritizaci"]},{"id":"estimate","g":"plan","word":"Odhad","text":"Nejlepší odhad, jak velký nebo jak dlouhý je kus práce. Je to odhad, ne slib.","also":["odhady","odhadování","estimate","estimation","odhadu","odhadů"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story pointy (body příběhu)","text":"Způsob odhadování velikosti práce porovnáváním karet mezi sebou („zhruba dvakrát větší než tahle“), ne v hodinách. Nejsou na porovnávání týmů.","also":["story points","story point","body příběhu","story pointy","story pointů"]},{"id":"tshirt","g":"plan","word":"Velikosti triček","text":"Odhad velikosti práce jako S, M, L nebo XL. Rychlé a pro rané plánování dost dobré.","also":["t-shirt sizing","t-shirt sizes","tričkové velikosti"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Hra na odhadování: všichni naráz ukážou kartu s velikostí a pak ti s nejvyšší a nejnižší vysvětlí proč.","also":["Scrum poker","plánovací poker","planning pokeru","planning poker"]},{"id":"dependency","g":"plan","word":"Závislost","text":"Když jedna práce nemůže začít ani skončit, dokud se neudělá jiná.","also":["dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Blokátor (překážka)","text":"Cokoli, co teď brání práci jít dál, třeba chybějící odpověď nebo rozbitý nástroj.","also":["blokátory","blocker","blockers","blokátoru","blokátorů"]},{"id":"deadline","g":"plan","word":"Termín","text":"Datum, do kterého musí být něco hotové.","also":["termíny","deadline","deadlines","termínu","termínů"],"noTip":1},{"id":"deliverable","g":"plan","word":"Výstup k předání","text":"Něco konkrétního, co práce vytvoří a předá, třeba fungující stránka nebo report.","also":["deliverable","deliverables","výstupy k předání"]},{"id":"forecast","g":"plan","word":"Prognóza","text":"Předpověď toho, co se pravděpodobně stane, třeba kdy bude práce hotová, podle toho, co zatím víš.","also":["prognózy","předpověď","forecast","forecasts","prognózu","prognóz"],"noTip":1},{"id":"metric","g":"plan","word":"Metrika","text":"Cokoli, co měříš a sleduješ v čase, třeba návštěvy stránky nebo jak dlouho trvá oprava.","also":["metriky","metric","metrics","metriku","metrik"]},{"id":"feedback","g":"plan","word":"Zpětná vazba (feedback)","text":"Co lidé říkají o tvé práci, dobré i špatné. Získávat ji brzy a často je srdce Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Seznam čekajících nápadů a práce, která ještě není naplánovaná, s nejdůležitějším nahoře. Nic z toho se nedělá, dokud to nepřejde do K udělání."},{"id":"sprint","g":"agile","word":"Sprint","text":"Krátký pevný úsek práce (často jeden nebo dva týdny, nikdy víc než měsíc) s cílem a domluvenou sadou karet, které se mají dokončit.","also":["sprinty","sprintu","sprintů","sprintem","sprintech"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Rychlé denní setkání: co kdo z týmu udělal, co dělá dál a co mu brání. Ve Scrumu se mu říká daily scrum.","also":["standup","stand-upy","daily scrum","daily stand-up","denní porada"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Způsob práce, kdy se karty posouvají přes sloupce boardu (jako K udělání, Rozpracováno, Hotovo) a tým omezuje, kolik jich je rozpracovaných najednou, aby práce plynula."},{"id":"wip","g":"agile","word":"WIP limit","text":"WIP je zkratka pro „work in progress“, tedy rozdělanou práci. WIP limit je největší počet karet, které by sloupec měl držet najednou, aby tým věci dokončoval, než začne další.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definice Hotovo","text":"Krátký týmový seznam, co znamená „hotovo“, třeba otestováno a vysvětleno, než se karta předá tobě. Její dvojče, Definice Připraveno, říká, kdy je karta dost jasná, aby se na ní začalo.","also":["Definice Hotovo","Definice Připraveno","Definition of Done","Definition of Ready","DoD","DoR"]},{"id":"retro","g":"agile","word":"Retro","text":"Pravidelné ohlédnutí za tím, jak tým pracuje, aby se dohodl na jedné či dvou věcech, které příště zlepšit. Zkratka pro retrospektivu. V AI-gile retro navrhne změnu v tom, jak tým pracuje, a ty řekneš Jdi nebo Zatím ne.","also":["retrospektiva","retrospektivy","retrospective"]},{"id":"swarm","g":"agile","word":"Roj","text":"Všichni na palubu: mnoho lidí nechá jiné práce a společně opraví jednu naléhavou věc, dokud se nevyřeší. V AI-gile pomáhá každý tým na jednom projektu a ostatní projekty mezitím čekají.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Ve Scrumu člověk, který týmu pomáhá dobře pracovat: odstraňuje, co mu brání, drží schůzky na trati a učí dobré návyky, aniž by někomu šéfoval. V AI-gile Lead Scrum Master napříč všemi projekty odhaluje zaseknuté karty, postrkuje týmy a připomíná ti, co čeká.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile (agilní přístup)","text":"Práce v malých krocích: postavit trochu, často ukazovat skutečné výsledky, učit se z toho, co lidé říkají, a měnit plán za pochodu, místo aby se všechno plánovalo předem.","also":["agilní","agilní vývoj","Agile development","agile ways of working","agilní přístup","agilně","agilita"]},{"id":"manifesto","g":"agile","word":"Agilní manifest","text":"Krátké prohlášení, které v roce 2001 napsali tvůrci softwaru. Staví lidi, fungující výsledky, blízkou spolupráci se zákazníky a reakci na změny před těžké plány a papírování.","also":["Manifest agilního vývoje softwaru","Agile Manifesto","Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Vodopád (waterfall)","text":"Starší způsob práce: nejdřív všechno naplánovat, pak všechno postavit, pak všechno otestovat, jedna fáze po druhé. Pozdní změny jsou těžké a drahé.","also":["vodopádový model","waterfall","waterfall model"]},{"id":"iteration","g":"agile","word":"Iterace","text":"Jedno kolo, kdy se něco postaví, zkontroluje a vylepší. Agilní práce je řetěz takových kol a sprint je jedním z nich.","also":["iterace","iteration","iterations","iteraci","iterací"]},{"id":"increment","g":"agile","word":"Přírůstek (inkrement)","text":"Nový fungující kousek přidaný do produktu ve sprintu nebo kole práce, který zapadá do toho, co už tam bylo.","also":["inkrement","increment","increments","inkrementu"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Oblíbený agilní způsob práce: malý tým pracuje v krátkých sprintech k cíli, s danými rolemi a pár pravidelnými schůzkami na plánování, kontrolu a zlepšování."},{"id":"scrumteam","g":"agile","word":"Scrum tým","text":"Malá skupina, která dělá práci ve Scrumu: Product Owner, Scrum Master a vývojáři.","also":["Scrum týmy","Scrum team","Scrum teams","Scrum týmu","Scrum týmů"]},{"id":"ceremonies","g":"agile","word":"Scrum události","text":"Pravidelné schůzky ve Scrumu: plánování sprintu, daily scrum, sprint review a retro. Hodně lidí jim říká ceremonie.","also":["ceremonie","scrumové ceremonie","Scrum events","Scrum ceremonies","Scrum událostí","ceremonií"]},{"id":"sprintplan","g":"agile","word":"Plánování sprintu","text":"Schůzka na začátku sprintu, na které se tým shodne, proč je sprint důležitý, které karty vezme a jak začít.","also":["plánovací schůzka","sprint planning","planning meeting","plánování sprintů"]},{"id":"sprintgoal","g":"agile","word":"Cíl sprintu","text":"Jedna věta o tom, k čemu sprint slouží. Drobné úkoly se po cestě můžou měnit, hlavně když se cíl splní.","also":["cíle sprintu","sprint goal","sprint goals","cíl sprintu","cílů sprintu"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"Karty vybrané pro aktuální sprint spolu s plánem týmu, jak je udělat.","also":["backlog sprintu","sprint backlogs","sprint backlogu","sprint backlog"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"Celý seřazený seznam všeho, co by se pro produkt mohlo postavit, nejdůležitější nahoře. Mění se, jak se dozvídáš víc.","also":["backlog produktu","product backlogs","product backlogu","product backlog"]},{"id":"productgoal","g":"agile","word":"Cíl produktu","text":"Větší výsledek, ke kterému produkt míří a který týmu pomáhá vybrat, co dělat dál.","also":["cíle produktu","product goal","product goals"]},{"id":"refinement","g":"agile","word":"Zpřesňování backlogu","text":"Pravidelné procházení backlogu, aby se karty uklidily, rozdělily, seřadily a doplnily o detaily a byly připravené k převzetí. Říká se tomu i grooming backlogu.","also":["refinement","backlog refinement","backlog grooming","grooming","zpřesňování backlogu"]},{"id":"sprintreview","g":"agile","word":"Sprint review (představení sprintu)","text":"Schůzka na konci sprintu, kde tým ukáže, co dokončil, a vyslechne si, co si lidé myslí, aby se rozhodlo, co dál.","also":["sprint review","sprint reviews","představení sprintu"]},{"id":"demo","g":"agile","word":"Demo","text":"Předvedení hotové práce v chodu, živě, lidem, kteří o ni požádali.","also":["dema","ukázka","demo","demos","demu","ukázky"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox (časový limit)","text":"Pevně daný čas na něco. Když vyprší, skončíš, i když není všechno hotové.","also":["timeboxy","timeboxed","timeboxes","timeboxu","timeboxů"]},{"id":"velocity","g":"agile","word":"Rychlost týmu (velocity)","text":"Kolik práce tým obvykle dokončí ve sprintu, podle čeho se plánuje, kolik vzít příště. Není to známka toho, jak moc se lidé snaží.","also":["velocity","team velocity","rychlosti týmu"]},{"id":"capacity","g":"agile","word":"Kapacita","text":"Kolik práce může tým v daném období vzít, po odečtení dovolených a jiných povinností.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown graf","text":"Graf práce, která ve sprintu zbývá, klesající den za dnem. Když čára zůstává rovná, něco se zaseklo.","also":["burndown","burn-down chart","burndown chart","graf vyhořívání","burndown grafu"]},{"id":"burnup","g":"agile","word":"Burnup graf","text":"Graf hotové práce, která v čase roste, vedle celkového plánu, takže je vidět, kdy dojdeš do cíle.","also":["burnup","burn-up chart","burnup chart","graf vyhořívání nahoru","burnup grafu","graf dokončené práce"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"Samotný board: sloupec pro každou fázi práce a karty, které se posouvají napříč.","also":["Kanban boardy","kanbanová tabule","Kanban boards","Kanban boardu","kanbanové tabule"]},{"id":"pullsys","g":"agile","word":"Pull systém (tahový systém)","text":"Způsob práce, kdy se nová práce začne, až když má někdo místo ji vzít, místo aby se hrnula na plný talíř.","also":["tahový systém","pull system","pull-based","systém pull"]},{"id":"flow","g":"agile","word":"Tok (flow)","text":"Jak plynule se práce posouvá boardem. Dobrý tok znamená, že se karty hýbou a nehromadí se.","also":["flow","tok práce","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time (doba dodání)","text":"Jak dlouho to trvá od chvíle, kdy o něco někdo požádá, do chvíle, kdy je to hotové.","also":["doba dodání","lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time (doba cyklu)","text":"Jak dlouho trvá karta od chvíle, kdy se na ní opravdu začne pracovat, do chvíle, kdy je hotová.","also":["doba cyklu","cycle times"]},{"id":"throughput","g":"agile","word":"Propustnost (throughput)","text":"Kolik karet se dokončí za týden nebo za jakýkoli daný čas.","also":["throughput","výkonnost","throughput rate"]},{"id":"bottleneck","g":"agile","word":"Úzké hrdlo","text":"Jedna fáze, kde se práce hromadí a zpomaluje všechno za ní, jako úzké hrdlo láhve.","also":["úzká hrdla","bottleneck","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Plavecká dráha (swimlane)","text":"Řádek napříč boardem, který seskupuje karty jednoho druhu, třeba naléhavou práci nebo karty jednoho týmu.","also":["swimlane","swimlanes","swim lane","swimlany"]},{"id":"lean","g":"agile","word":"Lean (štíhlý přístup)","text":"Způsob práce, který vyřezává plýtvání (všechno, co zákazníkovi nepomáhá) a nechává práci plynout."},{"id":"waste","g":"agile","word":"Plýtvání","text":"V Lean všechno, co stojí úsilí, ale zákazníkovi nepomáhá, třeba čekání, předělávání nebo stavění věcí, které nikdo nepoužívá.","noTip":1},{"id":"kaizen","g":"agile","word":"Neustálé zlepšování","text":"Být pořád o trochu lepší pomocí malých pravidelných změn a pak ověřit, že pomohly. Jedním ze způsobů jsou retra. Říká se tomu i kaizen.","also":["kaizen","continuous improvement"]},{"id":"selforg","g":"agile","word":"Samoorganizující se tým","text":"Tým, který si sám rozhoduje, jak práci udělá, místo aby dostával pokyny krok za krokem.","also":["samoorganizace","samořídící se tým","self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Mezifunkční tým","text":"Tým, který má všechny dovednosti potřebné k tomu, aby práci dokončil sám, třeba návrh, stavění a testování.","also":["multifunkční tým","cross-functional","cross-functional team"]},{"id":"spike","g":"agile","word":"Spike (krátký průzkum)","text":"Krátký časově omezený průzkum, který odpoví na otázku, než se pustíš do skutečné práce.","also":["spike","spikes"]},{"id":"rework","g":"agile","word":"Přepracování (rework)","text":"Dělání práce znovu, protože napoprvé nebyla správně.","also":["rework","předělávky","reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Způsoby, jak používat Agile napříč mnoha týmy ve velké organizaci. SAFe (Scaled Agile Framework) je jeden dobře známý příklad.","also":["scaled Agile","škálování Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Složka projektu s kódem a celou historií commitů. Může být na tvém počítači, na GitHubu, nebo na obou místech.","also":["repozitář","repa","repu"]},{"id":"branch","g":"build","word":"Branch","text":"Samostatná linie práce v kódu, aby šlo dělat změny, aniž by se sáhlo na hlavní verzi.","also":["branche","branch","větev","větve"]},{"id":"commit","g":"build","word":"Commit","text":"Uložený snímek kódu s krátkou poznámkou o tom, co se změnilo. Vždy se k němu můžeš vrátit.","also":["commity","commitu","commitů","commitem"]},{"id":"push","g":"build","word":"Push","text":"Odeslání uložených snímků (commitů) z tohoto počítače do sdílené kopie online, třeba na GitHub, aby byly zálohované a mohli si je stáhnout ostatní."},{"id":"merge","g":"build","word":"Merge","text":"Spojení změn z jedné větve do druhé, obvykle zpátky do hlavní verze."},{"id":"pr","g":"build","word":"Pull request","text":"Žádost, aby se změny z větve zkontrolovaly a sloučily do hlavní verze. Některé weby tomu říkají merge request.","also":["PR","PRs","pull request","merge request"]},{"id":"refactor","g":"build","word":"Refaktor","text":"Uklizení kódu beze změny toho, co dělá: menší soubory, jasnější názvy, méně opakování."},{"id":"bug","g":"build","word":"Bug","text":"Něco, co nefunguje tak, jak by mělo.","also":["bugy","bugu","bugů","bugem"]},{"id":"peerreview","g":"build","word":"Vzájemná kontrola","text":"Druhý pár očí: někdo jiný než autor zkontroluje práci, než se dostane k tobě, takže projde méně chyb. V AI-gile každou kartu kontroluje jiná AI.","also":["code review","peer review","revize kódu"]},{"id":"code","g":"build","word":"Kód","text":"Napsané instrukce, které počítači říkají, co má dělat. Říká se mu i zdrojový kód.","also":["zdrojový kód","source code","code","kódu","kódem"],"noTip":1},{"id":"proglang","g":"build","word":"Programovací jazyk","text":"Jazyk pro psaní kódu, třeba JavaScript, Python nebo Java. Různé se hodí na různé práce.","also":["programovací jazyky","programming language","programming languages"]},{"id":"developer","g":"build","word":"Vývojář (dev)","text":"Někdo, kdo píše a mění kód. Říká se mu i programátor nebo softwarový inženýr.","also":["dev","programátor","vývojáři","developer","developers","programmer","programmers","software engineer","softwarový inženýr","vývojáře","vývojářů","vývojářka","programátora","programátoři"]},{"id":"software","g":"build","word":"Software","text":"Programy, které běží na počítačích a telefonech, na rozdíl od samotných strojů (hardwaru).","noTip":1},{"id":"app","g":"build","word":"Aplikace","text":"Program, který lidé používají, aby něco vyřídili, na telefonu, počítači nebo ve webovém prohlížeči.","also":["aplikace","app","apps","application","applications","appka","aplikaci","aplikací","appky"],"noTip":1},{"id":"webapp","g":"build","word":"Webová aplikace","text":"Aplikace, která běží ve webovém prohlížeči, takže se nic neinstaluje.","also":["webové aplikace","web app","web apps","web application","webovou aplikaci","webových aplikací"]},{"id":"frontend","g":"build","word":"Front end","text":"Část aplikace, kterou vidíš a na kterou klikáš: obrazovky, tlačítka a texty, často ve tvém prohlížeči.","also":["frontend","front-end"]},{"id":"backend","g":"build","word":"Back end","text":"Část aplikace, která pracuje v zákulisí, drží data a dělá práci, když na něco klikneš, třeba kontroluje tvé heslo.","also":["backend","back-end"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Práce na front endu i na back endu.","also":["full-stack","fullstack"]},{"id":"ui","g":"build","word":"Uživatelské rozhraní (UI)","text":"Co člověk vidí a používá na obrazovce: rozvržení, tlačítka, nabídky a text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"Uživatelský zážitek (UX)","text":"Jaký je to pocit něco používat: snadné, jasné a příjemné, nebo zmatené a pomalé.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Přístupnost (a11y)","text":"Dělání věcí použitelných pro všechny, i pro lidi, kteří špatně vidí, nemohou používat myš nebo používají čtečku obrazovky.","also":["a11y","accessibility","bezbariérovost"]},{"id":"responsive","g":"build","word":"Responzivní design","text":"Úprava stránek tak, aby se vešly a dobře fungovaly na jakékoli obrazovce, od telefonu po velký monitor.","also":["responzivita","RWD"]},{"id":"designsys","g":"build","word":"Design systém","text":"Společná sada barev, písem, tlačítek a pravidel, aby každá obrazovka vypadala a chovala se stejně.","also":["design system","design systems","design systémy"]},{"id":"architecture","g":"build","word":"Architektura","text":"Celkový tvar systému: jaké jsou hlavní části a jak spolu mluví."},{"id":"database","g":"build","word":"Databáze (DB)","text":"Uspořádané úložiště informací, jako velmi silná tabulka, kterou aplikace umí číst a měnit.","also":["databáze","database","databases","DB","databázi","databází"]},{"id":"schema","g":"build","word":"Schéma databáze","text":"Rozvržení databáze: jaké tabulky s informacemi má a co patří do které.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Zkratka pro „structured query language“: jazyk, kterým se lze mnoha databází ptát na informace nebo je měnit.","also":["Structured Query Language","strukturovaný dotazovací jazyk"]},{"id":"data","g":"build","word":"Data","text":"Informace uložené v počítači, třeba jména, objednávky nebo nastavení.","also":["datová sada","datové sady","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"Počítač, který je pořád zapnutý a odpovídá na žádosti jiných počítačů, třeba pošle webovou stránku, když ji navštívíš.","also":["servery","servers","serveru","serverů","serverem"]},{"id":"client","g":"build","word":"Klient","text":"Strana, která o něco žádá, obvykle tvůj prohlížeč nebo aplikace, a mluví se serverem. V byznysu to znamená také prostě zákazníka.","also":["klienti","client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Zkratka pro „application programming interface“: pevné menu žádostí, které může jeden program posílat druhému, jako když se služby s předpovědí počasí zeptáš na dnešní předpověď.","also":["APIs","application programming interface","programovací rozhraní"]},{"id":"endpoint","g":"build","word":"Endpoint (koncový bod)","text":"Jedna položka z menu API: webová adresa, na kterou se program může obrátit, aby něco dostal nebo poslal.","also":["endpointy","koncový bod","endpoints"]},{"id":"integration","g":"build","word":"Integrace","text":"Propojení dvou systémů, aby spolupracovaly, třeba tvůj obchod posílá objednávky do účetního programu.","also":["integrace","integration","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"Zpráva, kterou jeden systém sám pošle druhému ve chvíli, kdy se něco stane, třeba „platba přijata“.","also":["webhooky","webhooks"]},{"id":"library","g":"build","word":"Knihovna","text":"Hotový kód, který napsal někdo jiný a který můžeš znovu použít, místo abys ho psal(a) od nuly.","also":["knihovny","library","libraries","knihovnu","knihoven"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"Hotová struktura pro stavbu aplikace, která z velké části určuje, jak je kód uspořádaný, jako kostra domu, kterou vyplníš.","also":["frameworky","aplikační rámec","frameworks","frameworku","frameworků"]},{"id":"sdk","g":"build","word":"Sada nástrojů pro vývojáře (SDK)","text":"Krabice nástrojů, kódu a příkladů pro tvorbu softwaru pro jednu platformu nebo službu.","also":["SDK","SDKs","software development kit"]},{"id":"softdep","g":"build","word":"Softwarová závislost","text":"Knihovna nebo nástroj, který tvůj kód potřebuje, aby fungoval. Udržovat je aktuální je důležité kvůli bezpečnosti.","also":["softwarové závislosti","software dependency","software dependencies"]},{"id":"package","g":"build","word":"Balíček","text":"Svazek hotového kódu, který můžeš nainstalovat a použít v projektu.","also":["balíčky","package","packages","balíčku","balíčků"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Správce balíčků","text":"Nástroj, který stahuje a aktualizuje balíčky, na kterých tvůj kód závisí. npm je častý příklad.","also":["správci balíčků","package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Nejrozšířenější nástroj pro uchování historie změn kódu, ve formě commitů a větví."},{"id":"github","g":"build","word":"GitHub","text":"Web, který drží Git repozitáře online, aby týmy mohly sdílet kód, kontrolovat změny a sledovat práci."},{"id":"vcs","g":"build","word":"Správa verzí","text":"Uchovávání úplné historie každé změny souborů, takže je vidět, kdo co změnil, a v případě potřeby se dá vrátit zpět. Dělá to Git.","also":["systém správy verzí","verzování","version control","source control","version control system"]},{"id":"clone","g":"build","word":"Klonování (clone)","text":"Vytvoření vlastní plné kopie repozitáře i s historií na tvém počítači.","also":["klonovat","naklonovat","clone","cloned","cloning"]},{"id":"pull","g":"build","word":"Pull (stažení změn)","text":"Stažení nejnovějších commitů ze sdílené kopie (třeba GitHubu) do tvého počítače. Opak pushe.","also":["pull","git pull","stáhnout změny"],"noTip":1},{"id":"mainbranch","g":"build","word":"Hlavní větev (main)","text":"Oficiální verze kódu, ze které všichni vycházejí, často zvaná main nebo master.","also":["hlavní větev","main branch","master branch","master"]},{"id":"conflict","g":"build","word":"Konflikt při slučování","text":"Když se dvě změny dotknou stejných řádků různým způsobem, takže je počítač nedokáže spojit a musí vybrat člověk.","also":["konflikty při slučování","merge konflikt","merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"Diff (rozdíly)","text":"Pohled, který přesně ukazuje, co se změnilo mezi dvěma verzemi: přidané řádky a odebrané řádky.","also":["diff","diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Tvoje vlastní kopie cizího repozitáře, kterou můžeš měnit, aniž by se změnil originál.","also":["forky","fork","forks","forked"]},{"id":"script","g":"build","word":"Skript","text":"Krátký program, který sám udělá jednu práci, třeba uklidí soubory nebo spustí aplikaci.","also":["skripty","script","scripts","skriptu","skriptů"],"noTip":1},{"id":"build","g":"build","word":"Build (sestavení)","text":"Přeměna kódu na něco připraveného ke spuštění, nebo samotný výsledek připravený ke spuštění.","also":["build","builds","buildy","sestavení","buildu","buildů"],"noTip":1},{"id":"compile","g":"build","word":"Kompilace","text":"Přeložení kódu napsaného lidmi do podoby, kterou počítač může spustit přímo.","also":["kompilovat","kompilátor","compile","compiler"]},{"id":"cli","g":"build","word":"Příkazový řádek (CLI)","text":"Textové okno, do kterého píšeš počítači pokyny, místo klikání. Říká se mu i terminál.","also":["příkazový řádek","terminál","konzole","command line","command-line","CLI"]},{"id":"config","g":"build","word":"Konfigurace (config)","text":"Nastavení, která řídí chování softwaru, držená stranou od kódu, aby se snadno měnila.","also":["config","configuration","nastavení","konfigurace","konfiguraci"],"noTip":1},{"id":"envvar","g":"build","word":"Proměnná prostředí","text":"Nastavení předané programu při spuštění, často pro adresy nebo hesla, aby nebyla zapsaná přímo v kódu.","also":["proměnné prostředí","environment variable","environment variables","env var"]},{"id":"debugging","g":"build","word":"Ladění (debugging)","text":"Hledání, proč něco nefunguje, a oprava.","also":["ladění","debug","debugged","debugging","debugovat"]},{"id":"pairing","g":"build","word":"Párové programování","text":"Dva lidé (nebo člověk a AI) pracují společně na stejném kódu, jeden píše a druhý kontroluje.","also":["pair programming","pairing","práce v páru"]},{"id":"docs","g":"build","word":"Dokumentace (docs)","text":"Psané vysvětlení, jak něco funguje nebo jak to používat.","also":["dokumentace","docs","documentation","dokumentaci"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"První soubor, který si v repozitáři přečíst: co projekt je a jak ho rozběhnout.","also":["READMEs","soubor README"]},{"id":"legacy","g":"build","word":"Legacy systém (zděděný)","text":"Starší systém, který se pořád používá a těžko se mění, často proto, že mu už rozumí málo lidí.","also":["legacy","legacy kód","legacy system","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technický dluh","text":"Zkratky, které teď šetří čas, ale zpomalují pozdější změny, jako půjčka, na kterou narůstají úroky. Refaktorováním se dluh splácí.","also":["technical debt","tech debt"]},{"id":"test","g":"test","word":"Test","text":"Kontrola, že něco funguje, jak má. Některé testy počítač spouští sám při každé změně kódu, jiné jsou tvoje vyzkoušení hotové karty, než ji přijmeš.","also":["testy","testu","testů","testování","testovat","otestuješ","otestovat"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Zkratka quality assurance (zajištění kvality): všechno, co se dělá, aby práce byla správná, než půjde do produkce. V AI-gile jsou to automatické kontroly: když je QA červené, něco selhalo a do produkce to nemůže, dokud se to neopraví.","also":["kontroly kvality","zajištění kvality","quality checks"]},{"id":"testpile","g":"test","word":"Balík testů","text":"Hotové karty, které čekají, až je vyzkoušíš, jedna po druhé. Jednu přijmi nebo ji pošli zpět s poznámkou a přijde další.","also":["balíky testů","test pile"]},{"id":"autotest","g":"test","word":"Automatický test","text":"Kontrola, kterou počítač spouští sám při každé změně kódu, aby včas odhalil chyby.","also":["automatické testy","automated test","automated tests","automatic tests","automatického testu","automatických testů"]},{"id":"manualtest","g":"test","word":"Ruční test","text":"Člověk práci ručně vyzkouší, aby zjistil, jestli se chová, jak má.","also":["ruční testy","ruční testování","manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test (jednotkový test)","text":"Malá automatická kontrola jednoho drobného kousku kódu samostatně.","also":["jednotkové testy","unit test","unit tests","unit testy","unit testů","jednotkových testů"]},{"id":"integtest","g":"test","word":"Integrační test","text":"Kontrola, že několik částí funguje správně pohromadě, ne jen každá zvlášť.","also":["integrační testy","integration test","integration tests","integračního testu","integračních testů"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"Test, který jedná jako skutečný uživatel od začátku do konce, třeba se zaregistruje, nakoupí a zaplatí.","also":["E2E","end-to-end testy","end-to-end tests"]},{"id":"uat","g":"test","word":"Uživatelské akceptační testování (UAT)","text":"Lidé, kteří si práci objednali, ji sami vyzkouší a řeknou, jestli dělá, co potřebují. Balík testů v AI-gile je jeho obdoba.","also":["UAT","akceptační testování","acceptance testing"]},{"id":"regression","g":"test","word":"Regrese","text":"Něco, co dřív fungovalo, ale po změně se rozbilo. Regresní testy kontrolují, že staré věci pořád fungují.","also":["regrese","regresní test","regresní testy","regression","regressions","regression test","regression tests","regression testing","regresi","regresí"]},{"id":"smoke","g":"test","word":"Smoke test (kouřový test)","text":"Velmi rychlá kontrola, jestli hlavní věci vůbec fungují, třeba hned poté, co se změna dostane naživo. Když neprojde, zastav se a podívej se.","also":["kouřový test","kouřové testy","smoke tests"]},{"id":"exploratory","g":"test","word":"Průzkumné testování","text":"Volné zkoušení produktu a šťourání do něj různými způsoby, aby se našly problémy, které by plánované kontroly minuly.","also":["průzkumný test","exploratory testing","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Testovací případ","text":"Jeden sepsaný scénář k vyzkoušení: kroky a co by se mělo stát.","also":["testovací případy","test case","test cases","testovacího případu","testovacích případů"]},{"id":"coverage","g":"test","word":"Pokrytí testy","text":"Kolik kódu hlídají automatické testy. Víc je obvykle bezpečnější, ale samotné vysoké pokrytí nedokazuje, že to funguje dobře.","also":["pokrytí kódu","test coverage","code coverage"]},{"id":"testdata","g":"test","word":"Testovací data","text":"Vymyšlené ukázkové informace používané při testování, aby se neprozradily soukromé údaje skutečných lidí.","also":["test data","test fixtures"]},{"id":"edgecase","g":"test","word":"Okrajový případ","text":"Neobvyklá situace na hraně, třeba prázdný formulář nebo jméno s apostrofem, kde se věci často rozbíjejí.","also":["okrajové případy","edge case","edge cases","okrajového případu","okrajových případů"]},{"id":"happypath","g":"test","word":"Happy path (ideální průchod)","text":"Běžná cesta, kdy všechno jde dobře. Dobré testování zkouší i ty méně šťastné."},{"id":"perftest","g":"test","word":"Výkonnostní testy","text":"Zjišťování, jak rychle něco běží a jak to zvládá zátěž.","also":["výkonnostní test","performance testing","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Zátěžové testy","text":"Zjišťování, jak systém zvládá, když ho používá hodně lidí naráz.","also":["zátěžový test","load testing","load test","load tests"]},{"id":"sectest","g":"test","word":"Bezpečnostní testy","text":"Hledání slabin, kterými by někdo mohl systém zneužít nebo vidět, co by neměl.","also":["bezpečnostní test","security testing","security test","security tests"]},{"id":"accesstest","g":"test","word":"Testy přístupnosti","text":"Kontrola, že produkt můžou používat lidé s různými schopnostmi, i se čtečkou obrazovky nebo jen s klávesnicí.","also":["test přístupnosti","accessibility testing","accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"Automatická kontrola, která odhaluje pravděpodobné chyby a nepořádný styl v kódu, jako kontrola pravopisu pro programy.","also":["linter","lint","lintování"]},{"id":"static","g":"test","word":"Statická analýza","text":"Hledání problémů v kódu tím, že se automaticky přečte, bez spuštění.","also":["statická analýza kódu","static analysis","static code analysis"]},{"id":"flaky","g":"test","word":"Nestabilní test (flaky)","text":"Test, který někdy projde a někdy neprojde bez jasného důvodu, takže se mu nedá úplně věřit.","also":["flaky","flaky test","flaky tests","nestabilní testy","nestabilního testu","nestabilních testů"]},{"id":"repro","g":"test","word":"Reprodukce chyby (repro)","text":"Vyvolání chyby znovu schválně podle stejných kroků, aby se dala prozkoumat a opravit. Sepsání těch kroků je nejužitečnější část hlášení chyby.","also":["repro","reproduce","steps to reproduce","kroky k reprodukci"]},{"id":"severity","g":"test","word":"Závažnost chyby (severity)","text":"Jak vážný je dopad problému, od drobného obtěžování po zastavení všeho.","also":["severity","úroveň závažnosti","severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Zkopírování nové verze softwaru na počítače, které ji provozují, třeba na testovací kopii nebo na ostrou službu."},{"id":"release","g":"change","word":"Vydání","text":"Pojmenovaný balík hotové práce, který jde do produkce najednou, s krátkými poznámkami, co se změnilo. 🚀 Vydání napíše poznámky z hotových karet.","also":["release","verze"]},{"id":"rollback","g":"change","word":"Rollback","text":"Návrat k poslední verzi, která fungovala, když nová dělá potíže. V AI-gile tlačítko ↩ Vrátit zpět shromáždí kroky pro vrácení, zapsané u každé změny, do jednoho kontrolního seznamu.","also":["vrácení zpět","vrátit zpět","roll back"]},{"id":"live","g":"change","word":"Produkce","text":"Skutečná verze, kterou lidé používají, na rozdíl od kopie na zkoušení. Vývojáři tomu říkají produkce nebo ostrý provoz.","also":["živě","ostrý provoz","production","live"],"noTip":1},{"id":"change","g":"change","word":"Změna","text":"Plánovaná změna něčeho, na co se lidé spoléhají, nejdřív sepsaná: co, proč, riziko, kdy a jak ji vrátit. Založ ji přes 🔀 Zadat změnu.","also":["změny","požadavek na změnu","change request"],"noTip":1},{"id":"risk","g":"change","word":"Riziko","text":"Něco, co se může pokazit, ohodnocené podle toho, jak je to pravděpodobné a jak zlé by to bylo. ⚠️ Rizika je drží v jednom seznamu, nejvyšší skóre nahoře, každé s datem, kdy se na něj znovu podívat.","also":["rizika","registr rizik"]},{"id":"chgwin","g":"change","word":"Okno změn","text":"Časy, kdy smějí změny jít do produkce, třeba klidný úterní večer. Mimo okno nejde kartu změny dokončit, pokud nejde o nouzový případ.","also":["okna změn","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Poslední kontrola těsně předtím, než změna půjde do produkce: každý, kdo musí schválit, řekne Go nebo No go. Pokračuje se jen tehdy, když všichni řeknou Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Schválení","text":"Čekání na „ano“, než začne práce. Karta, kterou zadá přítel, nebo změna čeká ve ✅ Schválení, dokud ji neschválíš nebo neodmítneš.","also":["schvalování","approval"]},{"id":"quiettime","g":"change","word":"Tichý čas","text":"Úsek času, třeba živý stream, ukázka nebo noc, kdy nic nejde do produkce. Týmy dál pracují a testují, ale nasazení počká, až skončí. Jinde se tomu říká zmrazení změn.","also":["tiché časy","zmrazení změn","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Způsob práce, kdy lidé, kteří software staví, a lidé, kteří ho provozují, tvoří jeden tým a hodně automatizují, takže změny jdou naživo často a bezpečně."},{"id":"cicd","g":"change","word":"CI/CD (průběžná integrace a dodávka)","text":"Změny všech se často spojují s hlavní verzí a pokaždé se automaticky kontrolují (průběžná integrace), takže software je vždy připravený jít naživo na stisk tlačítka (průběžná dodávka).","also":["CI/CD","CI","CD","continuous integration","continuous delivery","průběžná integrace","průběžná dodávka"]},{"id":"contdeploy","g":"change","word":"Průběžné nasazování","text":"O krok dál než průběžná dodávka: každá změna, která projde kontrolami, jde naživo sama, bez tlačítka ke stisknutí.","also":["continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"Automatická řada kroků, kterými změna prochází na cestě naživo, třeba build, testy a pak nasazení.","also":["pipeline","pipelines","pipeliny","pipelinu","CI pipeline"]},{"id":"environment","g":"change","word":"Prostředí","text":"Jedna oddělená kopie systému pro jeden účel, třeba jedna na vývoj, jedna na testování a ta ostrá.","also":["prostředí","environment","environments","prostředím"],"noTip":1},{"id":"devenv","g":"change","word":"Vývojové prostředí","text":"Kopie, ve které pracuje vývojář, často na vlastním počítači, kde rozbití věcí nikomu neublíží.","also":["dev prostředí","development environment","dev environment"]},{"id":"testenv","g":"change","word":"Testovací prostředí","text":"Oddělená kopie systému používaná jen na testování, aby se nesahalo na skutečnou službu.","also":["testovací prostředí","test environment","test environments"]},{"id":"staging","g":"change","word":"Staging (předprodukční prostředí)","text":"Poslední kopie nastavená stejně jako ostrý provoz, na závěrečnou kontrolu, než změna půjde naživo.","also":["staging","předprodukční prostředí","staging environment"]},{"id":"artifact","g":"change","word":"Artefakt buildu","text":"Soubor nebo balík, který build vyrobí, připravený k uložení, kontrole nebo nasazení naživo.","also":["artefakty buildu","build artifact","build artifacts","artefakt"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"Naléhavá oprava rychle nasazená mimo běžný plán, protože se rozbilo něco důležitého.","also":["hotfixy","hotfixes","naléhavá oprava","hotfixu","hotfixů"]},{"id":"patch","g":"change","word":"Záplata (patch)","text":"Malá aktualizace, která opraví chybu nebo zalepí bezpečnostní díru. Bezpečnostní záplaty se vyplatí nasazovat rychle.","also":["záplaty","patch","patches","security patch","security patches","bezpečnostní záplata","záplatu","záplat"]},{"id":"version","g":"change","word":"Číslo verze","text":"Označení jako 2.4.1, které říká, kterou verzi máš. První číslo se často mění při velkých změnách a poslední při malých opravách.","also":["čísla verzí","sémantické verzování","version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Poznámky k vydání","text":"Krátký srozumitelný seznam toho, co se ve vydání změnilo, pro lidi, kteří ho používají, včetně oprav a známých omezení. Říká se mu i changelog.","also":["changelog","change log","seznam změn","release notes"]},{"id":"flag","g":"change","word":"Feature flag (příznak funkce)","text":"Zapínač a vypínač funkce, díky kterému může nová práce jít naživo skrytá a pak se zapnout (nebo zase vypnout) bez nového vydání.","also":["příznak funkce","feature flags","feature toggle","feature toggles","přepínač funkce","feature flagy","feature flagů","příznaky funkcí"]},{"id":"rollfwd","g":"change","word":"Roll forward (oprava dopředu)","text":"Oprava špatného vydání rychlým nasazením nové, opravené verze místo návratu ke staré.","also":["roll forward","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Kanárkové vydání (canary)","text":"Nasazení změny nejdřív pro malou skupinu a pro všechny až tehdy, když vypadá v pořádku. Název je podle kanárků, které horníci brali pod zem jako včasné varování.","also":["canary","canary release","canary releases","kanárkové vydání"]},{"id":"bluegreen","g":"change","word":"Nasazení blue-green","text":"Držení dvou kopií ostrého systému a přepnutí lidí na novou najednou, aby se šlo hned vrátit, kdyby se něco pokazilo.","also":["blue-green","blue green deployment","blue-green deployment"]},{"id":"zerodown","g":"change","word":"Nasazení bez výpadku","text":"Nasazení nové verze tak, aby služba pro uživatele nikdy nepřestala fungovat.","also":["zero downtime","zero-downtime","zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"Řízení změn","text":"Pomoc změnám, aby uspěly: zvážit riziko, získat správné schválení a vybrat dobrý čas. Říká se tomu i change management.","also":["change enablement","change management"]},{"id":"cab","g":"change","word":"Rada pro změny (CAB)","text":"Skupina, která posuzuje důležité změny a rozhoduje, jestli a kdy mohou proběhnout.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Standardní změna","text":"Změna s nízkým rizikem, dělaná pokaždé stejným osvědčeným způsobem, takže je schválená předem.","also":["standardní změny","standard change","standard changes"]},{"id":"normchange","g":"change","word":"Běžná změna","text":"Změna, kterou je třeba před realizací zkontrolovat a schválit.","also":["běžné změny","normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Nouzová změna","text":"Změna, která se musí udělat hned, aby se vyřešily vážné potíže nebo se jim předešlo, s odpovídajícím rychlejším schválením.","also":["nouzové změny","emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Automatizace","text":"Nechat počítač dělat opakovanou práci sám, aby to bylo rychlejší a pokaždé stejné.","also":["automatizovat","automation","automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastruktura","text":"Stroje, sítě a služby, na kterých software běží.","also":["infra","infrastructure"]},{"id":"iac","g":"change","word":"Infrastruktura jako kód (IaC)","text":"Popsání serverů a nastavení v souborech uložených spolu s kódem, aby se daly pokaždé postavit znovu úplně stejně.","also":["IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"Cloud","text":"Pronájem počítačů, úložiště a služeb od velkého poskytovatele přes internet, místo vlastních strojů.","also":["cloud","v cloudu","the cloud","cloud computing","cloudové služby"]},{"id":"provider","g":"change","word":"Poskytovatel cloudu","text":"Firma, která pronajímá výpočetní výkon přes internet, třeba Amazon Web Services (AWS), Microsoft Azure nebo Google Cloud.","also":["poskytovatelé cloudu","cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Místo, kde tvoje aplikace nebo web žije a běží, aby se k nim lidé dostali, obvykle pronajaté od firmy.","also":["hostování"]},{"id":"domain","g":"change","word":"Doménové jméno","text":"Webová adresa, kterou lidé píšou, třeba example.com. Pronajímá se na rok, takže se musí obnovovat.","also":["doména","domény","doménová jména","domain name","domain names","domain","doménu","domén"]},{"id":"dns","g":"change","word":"DNS","text":"Zkratka pro „domain name system“: adresář internetu, který mění jméno jako example.com na adresu správného počítače.","also":["systém doménových jmen","domain name system"]},{"id":"container","g":"change","word":"Kontejner","text":"Zapečetěný balík s aplikací a vším, co potřebuje, aby běžela stejně na jakémkoli počítači. Docker je nejznámější nástroj.","also":["kontejnery","container","containers","Docker","kontejneru","kontejnerů"],"noTip":1},{"id":"vm","g":"change","word":"Virtuální stroj (VM)","text":"Předstíraný počítač běžící uvnitř skutečného, takže jeden velký stroj může fungovat jako mnoho.","also":["VM","VMs","virtuální stroje","virtual machine","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless (bez serverů)","text":"Spouštění kódu bez starosti o jakékoli servery: poskytovatel ho spustí, když je třeba, a ty platíš za to, co využiješ."},{"id":"lb","g":"change","word":"Load balancer (vyvažovač zátěže)","text":"Něco, co rozdělí návštěvníky mezi několik serverů, aby žádný nebyl přetížený.","also":["load balancer","load balancers","vyvažování zátěže"]},{"id":"cache","g":"change","word":"Cache (mezipaměť)","text":"Po ruce držené úložiště nedávných výsledků, aby se totéž nemuselo znovu stahovat nebo počítat. Jeho vyčištění může spravit stránky, které vypadají zastarale.","also":["cache","mezipaměť","cachování","caches","caching","cached","mezipaměti","cache paměť"]},{"id":"cdn","g":"change","word":"Síť pro doručování obsahu (CDN)","text":"Celosvětová sada serverů, které drží kopie tvých stránek a obrázků poblíž návštěvníků, aby se rychle načítaly.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"Migrace","text":"Přesun dat nebo systémů ze starého uspořádání do nového, nebo opatrná změna toho, jak je databáze uspořádaná.","also":["migrace","migrace databáze","migration","migrations","database migration","migraci","migrací"]},{"id":"service","g":"run","word":"Služba","text":"Něco, co jsi postavil a na co se lidé spoléhají, třeba web nebo aplikace, o co se někdo stará, aby to dál fungovalo. Zaškrtni „Tento projekt je služba“ a napiš, co nabízí, kdo ji používá a kdo má pohotovost.","also":["služby","service"]},{"id":"uptimepct","g":"run","word":"Dostupnost v čase (uptime)","text":"Jakou část času služba funguje, obvykle v procentech. 99,9 % pořád dovoluje asi 43 minut výpadku za měsíc.","also":["uptime","procento dostupnosti","uptime percentage"]},{"id":"uptime","g":"run","word":"Kontrola dostupnosti","text":"Automatická kontrola každých pár minut, že tvoje služba pořád odpovídá. Když několikrát po sobě selže, AI-gile sám otevře kartu incidentu.","also":["kontroly dostupnosti","uptime checks"]},{"id":"statuspage","g":"run","word":"Stavová stránka","text":"Veřejná stránka, která ukazuje, jestli služba funguje (zelená, oranžová nebo červená), s nejnovější zprávou, aby se lidé, kteří ji používají, mohli podívat místo ptaní.","also":["stavové stránky","status page"]},{"id":"desk","g":"run","word":"Servisní pult","text":"Místo, kam přicházejí dotazy a hlášení od lidí, kteří tvou službu používají. AI-gile každé zařadí jako požadavek, incident nebo nápad a řekne, když vypadá jako něco, co už bylo nahlášeno.","also":["servisní pulty","helpdesk","podpora"]},{"id":"svcrequest","g":"run","word":"Servisní požadavek","text":"Někdo žádá o něco běžného, třeba nový účet nebo trochu pomoci, místo aby hlásil, že je něco rozbité. Čeká, až na něj přijde řada; incident jde první.","also":["servisní požadavky"]},{"id":"incident","g":"run","word":"Incident","text":"Něco, co je právě teď rozbité nebo nefunguje správně pro lidi, kteří to používají, třeba nefunkční nebo velmi pomalý web. Karta 🔥 incidentu předběhne frontu: zprovoznit to znovu má přednost.","also":["incidenty","incident"]},{"id":"major","g":"run","word":"Závažný incident","text":"Velký incident: zasaženo hodně lidí, nebo jsou v ohrožení peníze či data. Jedno tlačítko nasadí na něj všechny týmy (roj), vzbudí toho, kdo má pohotovost, a každých 30 minut si řekne o aktualizaci stavu.","also":["závažné incidenty","major incident"]},{"id":"oncall","g":"run","word":"Pohotovost","text":"Být ten, kdo odpovídá, když se něco rozbije, i v noci. Každá služba má člena týmu s pohotovostí, kterého při jejích incidentech budí jako prvního.","also":["pohotovostní služba","on call","on-call"]},{"id":"replyby","g":"run","word":"Termín odpovědi","text":"Jak dlouho smí karta čekat na první odpověď, třeba hodinu u incidentu. Pak dostane červené hodiny, aby se nic potichu nezapomnělo. Říká se tomu i cíl odezvy.","also":["termíny odpovědí","cíl odezvy","response target"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Krátké ohlédnutí po incidentu: co se stalo, co pomohlo a co změnit, bez obviňování kohokoli. Bez něj nejde incident uzavřít.","also":["postmortem","revize po incidentu"]},{"id":"problem","g":"run","word":"Problém","text":"Skrytá příčina za jedním nebo více incidenty. Karta 🧩 problému seskupí incidenty, které se pořád vracejí, aby se příčina našla a opravila nadobro.","also":["problémy","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Hlavní příčina","text":"Skutečný důvod, proč se něco rozbilo, ne jen to, co jsi viděl selhávat. Oprav hlavní příčinu a incident se přestane vracet.","also":["příčina","root cause"]},{"id":"workaround","g":"run","word":"Náhradní řešení","text":"Způsob, jak udržet věci v chodu, než bude hotová skutečná oprava, třeba restartovat něco, když se to zasekne. Zapíše se na kartu problému, aby to nikdo nemusel vymýšlet znovu.","also":["obejití","dočasné řešení","workaround"]},{"id":"knownerror","g":"run","word":"Známá chyba","text":"Problém, jehož příčina je pochopená a který má sepsané náhradní řešení, ale ještě není opravený. 🧩 Známé chyby je vypisují, aby všichni použili náhradní řešení místo nového pátrání.","also":["známé chyby","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Návod krok za krokem, jak opravit známý druh potíží, aby se to pokaždé udělalo stejně a rychle. Po velkém incidentu ti tým může jeden navrhnout ke schválení.","also":["runbooky","provozní příručka"]},{"id":"ci","g":"run","word":"Konfigurační položka","text":"Jedna věc, na které tvoje služba závisí, třeba server, doména, certifikát, klíč nebo dodavatel. 🗂️ Konfigurační položky je vypisují pro každou službu, takže vidíš, čeho se incident dotýká a co je potřeba obnovit nebo zálohovat.","also":["konfigurační položky"]},{"id":"expiry","g":"run","word":"Datum vypršení","text":"Datum, kdy něco přestane fungovat, pokud se neobnoví, třeba bezpečnostní certifikát webu nebo jeho webová adresa. AI-gile tato data hlídá a 30 dní předem vytvoří pro každé jednu kartu na obnovení, aby nic nepřestalo fungovat znenadání.","also":["data vypršení","vypršení","hlídání vypršení"]},{"id":"backup","g":"run","word":"Záloha","text":"Uložená kopie tvých dat z dřívějška, ke které se můžeš vrátit, když se něco ztratí nebo poškodí. AI-gile každý den zálohuje tvoje nástěnky.","also":["zálohy","backup"]},{"id":"restore","g":"run","word":"Obnova","text":"Vrácení dat ze zálohy. Záloha se doopravdy počítá, až když víš, že jde obnovit, takže stojí za to to občas vyzkoušet.","also":["obnovit","obnoveno","restore"]},{"id":"svcreview","g":"run","word":"Revize služby","text":"Ohlédnutí za jedním měsícem služby: otevřené a vyřešené incidenty, jak rychle lidé dostali odpověď, dostupnost a spotřebované tokeny. Měsíční revize to ukazuje pro každou službu.","also":["revize služeb","měsíční revize","měsíční revize služby"]},{"id":"accessreview","g":"run","word":"Kontrola přístupů","text":"Každých 90 dní kontrola, kdo se ještě dostane dovnitř: odkazy ke sdílení, role přátel a uložená hesla a klíče. Každé ponecháš nebo odebereš, aby staré přístupy nezůstávaly viset.","also":["kontroly přístupů"]},{"id":"improvements","g":"run","word":"Seznam vylepšení","text":"Všechno, v čem se tým rozhodl zlepšit, na jednom místě: návrhy z retra, úkoly z revizí a opravy problémů, každé se svým stavem. Najdeš ho pod 📈 Vylepšení.","also":["seznamy vylepšení","vylepšení"]},{"id":"tokencap","g":"run","word":"Limit tokenů","text":"Měsíční limit tokenů, které smějí agenti jedné služby spotřebovat. Při 80 % dostaneš varování; při 100 % jejich práce na pozadí počká do dalšího měsíce, nebo dokud limit nezvýšíš.","also":["limity tokenů"]},{"id":"svcmgmt","g":"run","word":"Správa služeb","text":"Všechno, co je potřeba k tomu, aby služba den za dnem zůstávala užitečná a fungovala pro lidi, kteří se na ni spoléhají.","also":["service management","řízení služeb"]},{"id":"itil","g":"run","word":"ITIL","text":"Hojně používaný průvodce dobrou správou služeb, který pokrývá třeba incidenty, problémy a změny. Název kdysi znamenal IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Správa IT služeb (ITSM)","text":"Provoz technologií jako služby pro lidi, s jasnými způsoby, jak řešit požadavky, incidenty, změny a zlepšení.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"Spravovaná služba","text":"Služba, kterou za tebe provozuje a stará se o ni někdo jiný, na základě dohody o tom, jak dobře musí fungovat.","also":["spravované služby","managed service","managed services"]},{"id":"svcowner","g":"run","word":"Vlastník služby","text":"Člověk, který odpovídá za službu jako celek: jak dobře funguje, kolik stojí a jak se zlepšuje.","also":["vlastníci služeb","service owner","service owners"]},{"id":"sla","g":"run","word":"Dohoda o úrovni služeb (SLA)","text":"Písemný slib zákazníkům, jak dobře bude služba fungovat, třeba „dostupná 99,9 % času“ nebo „odpověď do hodiny“, často s vrácením peněz, když se nedodrží.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Cíl úrovně služeb (SLO)","text":"Vlastní cíl týmu, jak dobře má služba v daném období fungovat, obvykle nastavený o něco přísněji než SLA, pro jistotu.","also":["SLO","SLOs","service level objective"]},{"id":"sli","g":"run","word":"Ukazatel úrovně služeb (SLI)","text":"Skutečné měření, které porovnáváš s cílem, třeba podíl návštěv, které se načetly v pořádku.","also":["SLI","SLIs","service level indicator"]},{"id":"availability","g":"run","word":"Dostupnost","text":"Jestli lidé mohou službu použít, když ji potřebují, často měřeno jako uptime.","also":["vysoká dostupnost","availability","high availability"]},{"id":"downtime","g":"run","word":"Výpadek (downtime)","text":"Doba, kdy služba nefunguje nebo je vypnutá, plánovaně i neplánovaně.","also":["downtime","down time"]},{"id":"errorbudget","g":"run","word":"Rozpočet chyb","text":"Malé množství selhání, které tvůj cíl spolehlivosti dovoluje. Dokud něco zbývá, můžeš se změnami riskovat, a když se vyčerpá, zpomalíš.","also":["error budget","error budgets"]},{"id":"outage","g":"run","word":"Výpadek služby (outage)","text":"Doba, kdy služba pro uživatele nefunguje nebo je vážně rozbitá.","also":["výpadky","outage","outages","výpadek","výpadku","výpadků"]},{"id":"degraded","g":"run","word":"Zhoršený provoz","text":"Funguje, ale špatně: pomalu, nebo s některými částmi mimo provoz.","also":["zhoršená služba","degraded","degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Automatické sledování služby pořád dokola, aby se problémy odhalily, nejlépe dřív, než si jich všimnou uživatelé.","also":["monitorování"]},{"id":"observability","g":"run","word":"Pozorovatelnost","text":"Jak dobře poznáš zvenčí, co se děje uvnitř systému, podle jeho logů, čísel a stop.","also":["observability","o11y"]},{"id":"log","g":"run","word":"Log (záznam)","text":"Průběžný deník, který program vede o tom, co dělá, a podle kterého se zjišťuje, co se pokazilo.","also":["logy","záznam","deník","log","logs","logging","logu","logů","záznamy"],"noTip":1},{"id":"trace","g":"run","word":"Trace (stopa)","text":"Záznam o tom, jak jeden požadavek putuje různými částmi systému, krok za krokem, a ukazuje, kde se zpomalil.","also":["trace","traces","tracing","trasování"]},{"id":"latency","g":"run","word":"Latence (zpoždění)","text":"Jak dlouho trvá, než něco odpoví, třeba čekání mezi kliknutím a objevením stránky.","also":["latency"]},{"id":"alert","g":"run","word":"Alert (upozornění)","text":"Automatická zpráva, že něco vyžaduje pozornost, třeba web neodpovídá.","also":["alerty","upozornění","alarm","alerts","alerting","alertu","alertů"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Únava z alertů","text":"Když je alertů tolik, že je lidé začnou ignorovat, i ty důležité.","also":["alert fatigue","alarm fatigue","únava z alarmů"]},{"id":"dashboard","g":"run","word":"Dashboard (přehledová nástěnka)","text":"Obrazovka, která na první pohled ukazuje nejdůležitější čísla a stavy.","also":["dashboardy","nástěnka","přehledová nástěnka","dashboards","dashboardu","dashboardů"],"noTip":1},{"id":"paging","g":"run","word":"Vyvolání pohotovosti (paging)","text":"Naléhavé volání nebo buzení pohotovostní osoby kvůli problému.","also":["paging","paged","pagování"]},{"id":"escalation","g":"run","word":"Eskalace","text":"Přizvání někoho s větší odborností nebo pravomocí, když se věc nedá vyřešit na současné úrovni, nebo ne dost rychle.","also":["eskalovat","eskalování","escalation","escalate","escalated","eskalaci","eskalací"]},{"id":"triage","g":"run","word":"Triáž","text":"Rychlé třídění příchozích problémů podle naléhavosti a důležitosti, aby se nejhorší vyřídily jako první.","also":["triage","třídění požadavků","triaged","triáži"]},{"id":"impact","g":"run","word":"Dopad (impact)","text":"Jak moc něco zasahuje lidi: kolik jich a jak vážně.","noTip":1},{"id":"urgency","g":"run","word":"Naléhavost","text":"Jak rychle je třeba se něčím zabývat. Dopad a naléhavost dohromady určují prioritu.","noTip":1},{"id":"plevels","g":"run","word":"Úrovně priority (P1, P2…)","text":"Štítky, jak je problém naléhavý. P1 je nejzávažnější a vyžaduje okamžitou akci.","also":["P1","P2","P3","P4","úrovně priority"]},{"id":"queue","g":"run","word":"Fronta tiketů","text":"Seznam požadavků a incidentů čekajících na převzetí.","also":["fronty tiketů","ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"První a druhá linie","text":"Úrovně podpory: první linie přijme hovor a opraví jednoduché věci, druhá má hlubší znalosti na těžší. Říká se tomu i tier 1 a tier 2.","also":["první linie","druhá linie","podpora první linie","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Velitel incidentu","text":"Jeden člověk, který vede reakci na incident, aby všichni věděli, kdo rozhoduje a kdo co dělá.","also":["velitelé incidentu","incident commander","incident commanders"]},{"id":"responsetime","g":"run","word":"Doba reakce","text":"Jak dlouho to trvá, než se někdo poprvé ujme požadavku nebo incidentu.","also":["doby reakce","response time","response times"]},{"id":"resolution","g":"run","word":"Doba vyřešení","text":"Jak dlouho trvá požadavek nebo incident úplně vyřídit, od nahlášení po opravu.","also":["doby vyřešení","resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Průměrná doba obnovy (MTTR)","text":"V průměru, jak dlouho trvá, než služba po poruše zase funguje. MTTR může znamenat trochu jiné věci, takže řekni, co měříš.","also":["MTTR","mean time to recover","mean time to restore"]},{"id":"mtbf","g":"run","word":"Průměrná doba mezi poruchami (MTBF)","text":"V průměru, jak dlouho služba běží, než se něco pokazí.","also":["MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"Databáze konfigurace (CMDB)","text":"Seznam všech konfiguračních položek a toho, jak spolu souvisejí, takže je vidět, co na čem závisí.","also":["CMDB","configuration management database"]},{"id":"asset","g":"run","word":"Aktivum (asset)","text":"Cokoli hodnotného, co vlastníš nebo za co platíš, aby služba běžela, třeba notebook, softwarová licence nebo doména.","also":["aktiva","asset","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Plánování kapacit","text":"Zajištění, aby bylo dost výpočetního výkonu, úložiště a lidí na to, co přijde.","also":["capacity planning","capacity plan","plán kapacit"]},{"id":"scaling","g":"run","word":"Škálování","text":"Zvládnutí většího počtu uživatelů tím, že stroji přidáš výkon (škálování nahoru), nebo přidáš další stroje (škálování do šířky).","also":["škálovat","scaling","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Kontinuita provozu","text":"Plány, jak udržet důležité věci v chodu, když se stane něco velkého, třeba ztráta kanceláře, klíčového dodavatele nebo počítačů.","also":["plán kontinuity","business continuity","business continuity plan"]},{"id":"dr","g":"run","word":"Obnova po havárii (DR)","text":"Plán a nástroje, jak službu znovu zprovoznit po něčem vážném, třeba po ztrátě celého datového centra.","also":["DR","disaster recovery","obnova po katastrofě"]},{"id":"rto","g":"run","word":"Cílová doba obnovy (RTO)","text":"Nejdelší doba, po kterou smí služba po katastrofě nefungovat, než musí zase běžet.","also":["RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"Cílový bod obnovy (RPO)","text":"Kolik posledních dat si můžeš dovolit ztratit, měřeno v čase. RPO jedna hodina znamená zálohy alespoň každou hodinu.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Redundance","text":"Mít připravené náhrady, třeba druhý server, aby jedno selhání službu nezastavilo.","also":["zálohování komponent","redundancy"]},{"id":"failover","g":"run","word":"Failover (přepnutí při selhání)","text":"Samočinné přepnutí na záložní systém, když ten obvyklý selže.","also":["failover","přepnutí při selhání","fail over"]},{"id":"spof","g":"run","word":"Jediný bod selhání","text":"Jedna součást, která s sebou stáhne všechno, když se rozbije, protože žádná záloha není.","also":["SPOF","single point of failure","single points of failure"]},{"id":"maintwin","g":"run","word":"Servisní okno","text":"Plánovaná doba, kdy může být služba kvůli údržbě pozastavená nebo pomalá, oznámená uživatelům předem.","also":["servisní okna","odstávka","maintenance window","maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Předání","text":"Předání práce, znalostí a odpovědnosti jinému člověku nebo týmu, aby nic nespadlo pod stůl.","also":["předání práce","handover","handovers"]},{"id":"kb","g":"run","word":"Znalostní báze","text":"Sbírka článků nápovědy a odpovědí, pro uživatele i pro tým.","also":["znalostní báze","knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Spokojenost zákazníků (CSAT)","text":"Skóre od uživatelů, jak byli spokojení, často zjišťované po uzavření požadavku.","also":["CSAT","customer satisfaction"]},{"id":"supplier","g":"run","word":"Dodavatel","text":"Externí firma, na kterou se spoléháš, třeba tvůj poskytovatel hostingu. Říká se mu i vendor nebo třetí strana.","also":["dodavatelé","vendor","vendors","third party","třetí strana","supplier","suppliers","dodavatele","dodavatelů"],"noTip":1},{"id":"retire","g":"run","word":"Vyřazení služby","text":"Trvalé vypnutí služby, bezpečně: informovat její uživatele, vyřídit její data a přístupy a zastavit její náklady.","also":["vyřazování služby","service retirement","retiring a service"]},{"id":"eol","g":"run","word":"Konec životnosti (EOL)","text":"Když produkt přestane od výrobce dostávat aktualizace nebo podporu, takže by se měl vyměnit.","also":["EOL","end-of-life","end of life"]},{"id":"cybersec","g":"sec","word":"Kybernetická bezpečnost","text":"Ochrana systémů a dat před vloupáním, krádeží a poškozením.","also":["kyberbezpečnost","cybersecurity","cyber security"]},{"id":"authn","g":"sec","word":"Autentizace","text":"Ověření, kdo někdo je, obvykle heslem nebo kódem. Často se zkracuje na authn.","also":["ověření totožnosti","authn","authentication"]},{"id":"authz","g":"sec","word":"Autorizace","text":"Ověření, co smí někdo dělat, když už víš, kdo to je. Často se zkracuje na authz.","also":["authz","authorisation","authorization"]},{"id":"mfa","g":"sec","word":"Vícefaktorové ověření (MFA)","text":"Přihlášení pomocí dvou či více důkazů, třeba heslo plus kód v telefonu. Říká se mu i dvoufaktorové ověření (2FA).","also":["MFA","2FA","dvoufázové ověření","two-factor","two-factor authentication","dvoufaktorové ověření"]},{"id":"sso","g":"sec","word":"Jednotné přihlášení (SSO)","text":"Jedno přihlášení, díky kterému se dostaneš do mnoha systémů, jako když všude používáš pracovní účet.","also":["SSO","single sign-on"]},{"id":"pwmgr","g":"sec","word":"Správce hesel","text":"Aplikace, která vytváří silná hesla a pamatuje si je za tebe.","also":["správci hesel","password manager","password managers"]},{"id":"secret","g":"sec","word":"Tajemství (secret)","text":"Heslo, klíč nebo jiný soukromý kód, který program používá, aby se k něčemu dostal. Nikdy se nesmí sdílet ani zapisovat do kódu.","also":["tajné údaje","secret","secrets","tajemství","tajného údaje"],"noTip":1},{"id":"apikey","g":"sec","word":"API klíč","text":"Tajný kód, který programu dovolí používat API jiné služby a ukazuje, kdo ji používá (a kdo za ni platí).","also":["API klíče","API key","API keys","API klíčů","API klíčem"]},{"id":"accesstoken","g":"sec","word":"Přístupový token","text":"Dočasná propustka, která dokazuje, že program může dovnitř, takže nepotřebuje pokaždé tvoje heslo. Není to totéž co AI token.","also":["přístupové tokeny","access token","access tokens"]},{"id":"encryption","g":"sec","word":"Šifrování","text":"Zamíchání informací tak, aby je mohl přečíst jen někdo se správným klíčem.","also":["šifrovat","zašifrované","encryption","encrypted","encrypt","šifrováním","zašifrovat"]},{"id":"https","g":"sec","word":"HTTPS","text":"Bezpečný způsob, jakým putují webové stránky, poznáš ho podle zámečku v prohlížeči, aby je nikdo cestou nemohl číst ani měnit."},{"id":"cert","g":"sec","word":"Certifikát SSL/TLS","text":"Digitální občanka, díky které web prokáže, kdo je, a může používat HTTPS. Vyprší, takže se musí obnovovat.","also":["TLS certifikát","SSL certifikát","certifikát","certifikáty","TLS certificate","SSL certificate","certificate","certificates","certifikátu","certifikátů"]},{"id":"permissions","g":"sec","word":"Oprávnění","text":"Pravidla, kdo smí co vidět nebo měnit.","also":["práva","povolení","permissions","permission","oprávněním","práv"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Princip nejmenších oprávnění","text":"Dávat každému člověku nebo programu jen takový přístup, jaký opravdu potřebuje, a jen na tak dlouho, na jak dlouho ho potřebuje.","also":["nejmenší oprávnění","least privilege","principle of least privilege"]},{"id":"rbac","g":"sec","word":"Řízení přístupu podle rolí (RBAC)","text":"Přidělování přístupu podle role, třeba čtenář nebo editor, místo člověk po člověku.","also":["RBAC","přístup podle rolí","role-based access"]},{"id":"vuln","g":"sec","word":"Zranitelnost","text":"Slabina, kterou by někdo mohl využít k vloupání nebo k napáchání škody.","also":["zranitelnosti","bezpečnostní díra","vulnerability","vulnerabilities","zranitelnost","zranitelností"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"Slabina, kterou útočníci znají dřív, než měli tvůrci vůbec čas ji opravit.","also":["zero-days","zero day","zero-day zranitelnost"]},{"id":"malware","g":"sec","word":"Malware (škodlivý software)","text":"Škodlivý software, třeba viry, vyrobený k poškozování, špehování nebo krádeži.","also":["malware","škodlivý software"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware, který zamkne tvoje soubory a žádá peníze za jejich odemčení. Dobré zálohy jsou nejlepší obrana.","also":["vyděračský software","útok ransomwaru","ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Falešné zprávy, které tě mají napálit: vylákat z tebe hesla nebo peníze, nebo tě přimět otevřít něco škodlivého.","also":["podvodný e-mail","phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Sociální inženýrství","text":"Napálení lidí, ne počítačů, aby dali přístup, třeba falešný telefonát od „IT podpory“."},{"id":"firewall","g":"sec","word":"Firewall","text":"Strážce, který rozhoduje, jaký síťový provoz smí dovnitř nebo ven.","also":["firewally","brána firewall","firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Zkratka pro „virtual private network“: soukromé, zašifrované spojení přes internet, často používané k bezpečnému přístupu k pracovním systémům.","also":["virtuální privátní síť","virtual private network"]},{"id":"ddos","g":"sec","word":"Útok odepření služby (DoS, DDoS)","text":"Zahlcení služby tolika falešným provozem, že ji skuteční lidé nemohou používat. DDoS znamená, že přichází z mnoha počítačů naráz.","also":["DoS","DDoS","denial of service","DDoS útok","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetrační test (pentest)","text":"Najmutí přátelských expertů, kteří se zkusí vloupat, aby se slabiny našly dřív, než je najdou skuteční útočníci.","also":["pentest","penetrační testy","pen test","pen testing","penetration testing"]},{"id":"audit","g":"sec","word":"Bezpečnostní audit","text":"Pečlivá kontrola, jak dobře je něco chráněno, podle seznamu dobrých postupů.","also":["bezpečnostní audity","security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Modelování hrozeb","text":"Promyšlení, kdo by mohl něco napadnout, jak, a co uděláš, abys mu v tom zabránil(a).","also":["model hrozeb","threat modelling","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Únik dat","text":"Když se soukromé informace dostanou k lidem, kteří je mít nemají, nebo se ztratí či změní bez povolení.","also":["úniky dat","narušení dat","data breach","data breaches","úniku dat","úniků dat"]},{"id":"pii","g":"sec","word":"Osobní údaje","text":"Jakákoli informace o člověku, kterého lze identifikovat, třeba jméno, e-mailová adresa nebo poloha. Říká se jim i PII.","also":["PII","personal data","personally identifiable information","osobních údajů","osobními údaji"]},{"id":"gdpr","g":"sec","word":"GDPR (obecné nařízení o ochraně osobních údajů)","text":"Evropské nařízení o osobních údajích (Spojené království má vlastní verzi): sbírej jen to, co potřebuješ, drž to v bezpečí a nech lidi, aby své údaje viděli nebo smazali.","also":["GDPR","General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Ochrana dat","text":"Správné zacházení s osobními údaji v souladu se zákonem.","also":["ochrana osobních údajů","data protection","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Zásady ochrany soukromí","text":"Veřejná stránka, která říká, jaké osobní údaje sbíráš, proč a co s nimi děláš.","also":["informace o zpracování údajů","privacy policy","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Souhlas","text":"Jasné, svobodné „ano“ člověka k tomu, aby se jeho údaje použily určitým způsobem. Může ho kdykoli vzít zpět.","also":["opt-in","consent","souhlas se zpracováním","souhlasu","souhlasem"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie (soubor cookie)","text":"Malý soubor, který si web uloží do prohlížeče, aby si něco pamatoval, třeba přihlášení. Některé vyžadují nejdřív tvůj souhlas.","also":["cookies","soubory cookie","cookie","sušenka","cookiesy","cookie lišta"],"noTip":1},{"id":"minimisation","g":"sec","word":"Minimalizace dat","text":"Sbírat a uchovávat jen ty osobní údaje, které opravdu potřebuješ pro danou práci.","also":["data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Uchovávání dat","text":"Jak dlouho se data uchovávají, než se smažou. Držet je jen tak dlouho, jak je třeba, je bezpečnější a často to vyžaduje zákon.","also":["doba uchovávání","retence dat","data retention","retention period"]},{"id":"anon","g":"sec","word":"Anonymizace","text":"Úprava dat tak, aby se podle nich už nikdo rozumně nedal identifikovat.","also":["anonymizované","anonymní data","anonymisation","anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymizace","text":"Nahrazení jmen a dalších údajů kódy, s klíčem uloženým stranou, který je zase spojí. Pořád jsou to osobní údaje.","also":["pseudonymizované","pseudonymisation","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Smlouva o zpracování osobních údajů (DPA)","text":"Smlouva, která říká, jak smí dodavatel nakládat s osobními údaji tvým jménem.","also":["DPA","zpracovatelská smlouva","data processing agreement"]},{"id":"dpia","g":"sec","word":"Posouzení vlivu na ochranu údajů (DPIA)","text":"Pečlivé zamyšlení před začátkem nad tím, jak může plán využití osobních údajů ovlivnit lidi a jak snížit rizika.","also":["DPIA","posouzení vlivu","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Auditní log","text":"Záznam o tom, kdo co udělal a kdy, aby se činnosti daly později zkontrolovat.","also":["auditní logy","auditní stopa","audit log","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Soulad s předpisy (compliance)","text":"Dodržování zákonů, pravidel a norem, které se tě týkají, a schopnost ukázat, že je dodržuješ.","also":["compliance","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Známá mezinárodní norma pro řízení informační bezpečnosti. Firmy se podle ní mohou nechat certifikovat.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Americká zpráva, ověřená externími auditory, která ukazuje, že firma o data zákazníků řádně pečuje.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"AI, která na úkolu pracuje sama: čte kód, dělá změny, spouští kontroly a hlásí výsledek. Její práce se přesto kontroluje.","also":["agenti","agenta","agentů"]},{"id":"token","g":"ai","word":"Token","text":"Malé kousky textu, které AI čte a píše, každý zhruba tři čtvrtiny slova. Využití AI se počítá v tokenech, takže méně tokenů nechá víc z tvého tarifu.","also":["tokeny","tokenů","tokenu","tokenech"]},{"id":"hook","g":"ai","word":"Hook","text":"Malý příkaz, který se sám spustí v určitou chvíli, například při startu relace AI, aby tým slyšel tvoje komentáře.","also":["hooky","hooku","hooků"]},{"id":"ai","g":"ai","word":"Umělá inteligence (AI)","text":"Počítačové systémy, které dělají věci, o kterých si obvykle myslíme, že na ně je potřeba člověk, třeba psaní, odpovídání na otázky nebo rozpoznávání obrázků.","also":["AI","artificial intelligence","umělá inteligence","umělé inteligence","umělou inteligenci"],"noTip":1},{"id":"ml","g":"ai","word":"Strojové učení (ML)","text":"Způsob, jak počítače učit vzorcům z mnoha příkladů, místo aby dostaly přesná pravidla.","also":["ML","machine learning"]},{"id":"model","g":"ai","word":"Model","text":"Natrénovaný „mozek“ AI systému, vzniklý učením z obrovského množství příkladů. Modely se liší schopnostmi, rychlostí a cenou.","also":["modely","AI model","models","modelu","modelů","modelem"],"noTip":1},{"id":"llm","g":"ai","word":"Velký jazykový model (LLM)","text":"Model AI natrénovaný na obrovském množství textu, takže umí číst a psát jazyk.","also":["LLM","LLMs","large language model","velký jazykový model","jazykového modelu","jazykových modelů"]},{"id":"genai","g":"ai","word":"Generativní AI","text":"AI, která vytváří nové věci, třeba texty, obrázky nebo kód, ne jen třídí nebo rozpoznává.","also":["GenAI","generative AI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Program, se kterým si povídáš běžným jazykem, psaním nebo mluvením.","also":["chatboti","chatbots","chatbota","chatbotů","chatbotem"]},{"id":"prompt","g":"ai","word":"Prompt","text":"Co dáš AI: svou otázku nebo pokyny a všechno, co jí předáš. Jasnější prompty obvykle dávají lepší odpovědi.","also":["prompty","zadání pro AI","prompts","promptu","promptů","promptem"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"Dovednost psát prompty, které dávají spolehlivé a užitečné výsledky.","also":["psaní promptů"]},{"id":"sysprompt","g":"ai","word":"Systémový prompt","text":"Pokyny na pozadí, které AI dostane před začátkem konverzace a které určují její roli a pravidla. Mají větší váhu než to, co napíšeš.","also":["systémové prompty","system prompt","system prompts","system instruction","system instructions","systémová instrukce"]},{"id":"context","g":"ai","word":"Kontext","text":"Všechno, co AI při práci vidí: pokyny, tvoje zprávy, soubory, které přečetla, a dřívější odpovědi.","noTip":1},{"id":"ctxwin","g":"ai","word":"Kontextové okno","text":"Kolik toho AI udrží v hlavě najednou, měřeno v tokenech. Za touto hranicí se starší části zahodí nebo shrnou.","also":["kontextová okna","context window","context windows"]},{"id":"session","g":"ai","word":"Relace","text":"Jedna pracovní konverzace s AI, od začátku do konce. Nová relace začíná s čistou pamětí.","also":["relace","session","sessions","relaci","relací"],"noTip":1},{"id":"memory","g":"ai","word":"Paměť","text":"Poznámky, které si AI drží mezi relacemi, aby si pamatovala tvoje preference a dřívější rozhodnutí.","noTip":1},{"id":"hallucination","g":"ai","word":"Halucinace","text":"Když AI řekne něco, co zní sebejistě, ale je to vymyšlené nebo špatně. Důležitá fakta si ověř.","also":["halucinace","halucinovat","hallucination","hallucinations","hallucinate","hallucinates","halucinuje","halucinací"]},{"id":"training","g":"ai","word":"Trénování","text":"Učení modelu tím, že se mu ukáže obrovské množství příkladů, ještě než ho kdokoli začne používat.","also":["trénink","natrénovaný","training","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Trénovací data","text":"Příklady, ze kterých se model učil. Jeho znalosti končí k datu, kdy se data sebrala.","also":["trénovací sada","training data","training set"]},{"id":"cutoff","g":"ai","word":"Hranice znalostí","text":"Datum, kde končí vestavěné znalosti AI. O pozdějších věcech neví, pokud si je nevyhledá.","also":["datum odříznutí znalostí","knowledge cutoff","training cutoff"]},{"id":"finetune","g":"ai","word":"Dolaďování (fine-tuning)","text":"Dodatečné trénování existujícího modelu na tvých vlastních příkladech, aby byl lepší v jedné konkrétní práci.","also":["fine-tuning","dolaďovat","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"Model AI, který se skutečně používá k odpovědi na něco, na rozdíl od trénování.","also":["inference","vyvozování","model inference"]},{"id":"tooluse","g":"ai","word":"Používání nástrojů","text":"AI, která umí něco dělat, ne jen mluvit: spouštět příkazy, číst soubory nebo hledat na webu, přes nástroje, které jí dá aplikace.","also":["tool use","volání nástrojů","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"Pomocná AI, které hlavní AI předá menší práci a dostane od ní výsledek zpět.","also":["subagenti","subagents","sub-agent","subagenta","subagentů"]},{"id":"multiagent","g":"ai","word":"Multiagentní přístup","text":"Několik AI pracuje společně na jedné věci, každá na své části, jako malý tým.","also":["multi-agent","multiagentní systém","multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomie","text":"Kolik toho smí AI udělat sama, než se musí zeptat člověka.","also":["autonomous","autonomní"]},{"id":"hitl","g":"ai","word":"Člověk ve smyčce","text":"Držet v procesu člověka, který v klíčových chvílích zkontroluje nebo schválí, co AI dělá. V AI-gile jsi to ty.","also":["human in the loop","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Ochranná zábradlí (guardrails)","text":"Omezení a kontroly, které drží kroky AI v bezpečí, třeba nutnost schválení, než cokoli půjde naživo. Snižují riziko chyb, ale nevylučují je.","also":["guardrails","guardrail"]},{"id":"rag","g":"ai","word":"RAG (generování podložené vyhledáním)","text":"AI si před odpovědí něco dohledá ve tvých dokumentech, takže její odpovědi stojí na tvých faktech.","also":["RAG","retrieval-augmented generation","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding (vektorová reprezentace)","text":"Přeměna textu na seznam čísel, který zachycuje jeho význam, aby počítač mohl najít věci s podobným významem.","also":["embeddingy","embedding","embeddings"]},{"id":"vectordb","g":"ai","word":"Vektorová databáze","text":"Databáze vytvořená k prohledávání takových seznamů čísel (embeddingů), aby našla materiál s podobným významem.","also":["vektorové databáze","vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Společný způsob, jak do AI aplikací zapojit nástroje a zdroje dat, aby je AI mohla používat.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Teplota","text":"Nastavení, jak odvážné jsou odpovědi AI. Nízká dává stálejší a předvídatelnější odpovědi, vysoká pestřejší. Ani jedna nezaručí, že má vždy pravdu.","also":["temperature","teplota modelu","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodální","text":"Schopný pracovat s více druhy informací, třeba s textem, obrázky a zvukem.","also":["multimodalita","multimodal","multi-modal"]},{"id":"evals","g":"ai","word":"Vyhodnocení (eval)","text":"Plánovaný test, jak dobře si AI vede na vybraných příkladech, aby se daly porovnat modely nebo prompty.","also":["eval","evals","evaluace"]},{"id":"bias","g":"ai","word":"Zaujatost (bias)","text":"Když se AI (nebo člověk) nespravedlivě kloní jedním směrem, často kvůli tomu, z čeho se učila.","also":["bias","předpojatost","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Odpovědná AI","text":"Používání AI férově, bezpečně a poctivě, tak aby za výsledky pořád odpovídali lidé.","also":["etická AI","responsible AI","ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"Trik, kdy skryté pokyny na webové stránce nebo v souboru zkouší přimět AI udělat něco, o co uživatel nežádal.","also":["vložení promptu","prompt injections"]},{"id":"ratelimit","g":"ai","word":"Limit požadavků (rate limit)","text":"Strop na to, kolik žádostí smíš službě poslat za daný čas. Když ho překročíš, musíš počkat.","also":["rate limit","limity požadavků","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Limit využití","text":"Kolik práce AI ti tarif v daném období dovolí; potom se práce pozastaví nebo stojí víc.","also":["limity využití","usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Tvorba softwaru hlavně tak, že AI popíšeš, co chceš, a necháš ji napsat kód.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Rozpočet","text":"Částka peněz vyčleněná na něco.","also":["rozpočty","budget","budgets","rozpočtu","rozpočtů"],"noTip":1},{"id":"costest","g":"money","word":"Odhad nákladů","text":"Nejlepší odhad, kolik něco bude stát, než začneš.","also":["kalkulace","cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"Návratnost investice (ROI)","text":"Co dostaneš zpátky ve srovnání s tím, co do toho vložíš. Když je kladná, vyplatilo se to.","also":["ROI","return on investment"]},{"id":"tco","g":"money","word":"Celkové náklady na vlastnictví (TCO)","text":"Všechno, co něco opravdu stojí za celou dobu života, ne jen kupní cena: provoz, podpora, vylepšení a nakonec vyřazení.","also":["TCO","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx a OpEx","text":"CapEx jsou peníze utracené předem za věci, které si necháš; OpEx jsou průběžné výdaje, třeba měsíční účty.","also":["CapEx","OpEx","kapitálové výdaje","provozní výdaje","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Předplatné","text":"Pravidelné placení, obvykle měsíčně nebo ročně, aby se dalo něco dál používat.","also":["předplatná","subscription","subscriptions","předplatného","předplatným"],"noTip":1},{"id":"saas","g":"money","word":"Software jako služba (SaaS)","text":"Software, který používáš online a platíš za něj předplatným, zatímco ho za tebe provozuje jeho tvůrce.","also":["SaaS","software as a service"]},{"id":"payg","g":"money","word":"Platba za využití","text":"Platit jen za to, co využiješ, jako u cloudu nebo AI tokenů.","also":["pay as you go","pay-as-you-go","usage-based pricing","platba podle spotřeby"]},{"id":"overage","g":"money","word":"Překročení tarifu (overage)","text":"Využití nad rámec toho, co tarif zahrnuje, což může stát navíc.","also":["overage","overages","overage charges","poplatky za překročení"]},{"id":"billingalert","g":"money","word":"Upozornění na útratu","text":"Zpráva, když útrata nebo využití dosáhne úrovně, kterou si zvolíš. Varuje tě, ale další poplatky nemusí vždy zastavit.","also":["upozornění na vyúčtování","billing alert","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Bezplatná úroveň","text":"Bezplatná úroveň placené služby, s omezeními. Hodí se na začátek.","also":["tarif zdarma","free tier","free plan"]},{"id":"pricing","g":"money","word":"Cenový plán","text":"Různé balíčky, které služba prodává, každý s vlastní cenou a limity.","also":["cenové plány","ceník","pricing plan","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"Pravidla, jak smíš používat, kopírovat, měnit nebo sdílet něco, co vyrobil někdo jiný, třeba software, písma nebo obrázky.","also":["licence","license","licenses","licenci","licencí"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software, jehož kód může kdokoli číst, používat a často i zdarma měnit podle pravidel jeho licence.","also":["otevřený software","otevřený kód","open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"Pravidla, která přicházejí s open source kódem. Některá dovolují skoro cokoli (jako MIT), jiná chtějí, aby se sdílely i tvoje změny (jako GPL).","also":["open source licence","licence MIT","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietární","text":"Vlastněný firmou a nesmí se volně kopírovat ani měnit. Opak open source.","also":["proprietární software","proprietary","proprietary software","uzavřený software"]},{"id":"copyright","g":"money","word":"Autorská práva","text":"Zákonné právo tvůrce řídit kopie svého díla, včetně kódu a textů.","also":["copyright","autorské právo","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Duševní vlastnictví (IP)","text":"Nápady a výtvory, které zákon považuje za něčí vlastnictví, třeba kód, návrhy, názvy a loga.","also":["IP","intellectual property"]},{"id":"tos","g":"money","word":"Obchodní podmínky","text":"Pravidla, se kterými souhlasíš, když službu používáš.","also":["podmínky používání","podmínky služby","terms of service","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Smlouva","text":"Písemná dohoda mezi dvěma stranami, kterou zákon podpoří.","also":["smlouvy","kontrakt","contract","contracts","smlouvu","smluv"],"noTip":1},{"id":"sow","g":"money","word":"Popis prací (SOW)","text":"Dokument, který přesně stanoví, jaká práce se udělá, do kdy a za kolik.","also":["SOW","statement of work","rozsah prací"]},{"id":"fixedprice","g":"money","word":"Pevná cena","text":"Dohodnutá cena za celou práci, bez ohledu na to, jak dlouho potrvá.","also":["paušál","fixed price","fixed-price"]},{"id":"tm","g":"money","word":"Čas a materiál","text":"Platba za skutečně odpracované hodiny a skutečně použité věci, místo pevné ceny.","also":["T&M","time and materials","platba za odpracované hodiny"]},{"id":"invoice","g":"money","word":"Faktura","text":"Účet s žádostí o zaplacení za odvedenou práci nebo dodané zboží.","also":["faktury","invoice","invoices","fakturu","faktur"],"noTip":1},{"id":"lockin","g":"money","word":"Závislost na dodavateli (lock-in)","text":"Když je odchod od dodavatele tak těžký nebo drahý, že u něj prakticky musíš zůstat.","also":["lock-in","vendor lock-in","uzamčení u dodavatele"]},{"id":"procurement","g":"money","word":"Nákup a zadávání zakázek","text":"Proces výběru dodavatelů a nakupování od nich.","also":["procurement","zadávání zakázek"]},{"id":"servicecredit","g":"money","word":"Servisní kredit","text":"Vrácené peníze nebo sleva, které dostaneš, když dodavatel nedodrží SLA.","also":["kompenzace za SLA","service credit","service credits"]}]}};
